INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp1','choice','{"stem":"\"The store ___ at nine every morning.\"(表习惯/规律:open)","options":["is opening","will open","opens","opened"],"answer_index":2,"stem_cn":"这家店每天早上九点开门。","explanation_cn":"经常、规律发生的事用一般现在时;主语 the store 第三人称单数,open 加 -s。✓ The store opens at nine every morning."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp1','choice','{"stem":"\"I ___ a lot of pictures.\"(经常做:一般现在时)","options":["am painting","painted","will paint","paint"],"answer_index":3,"stem_cn":"我画很多画。","explanation_cn":"\"我经常画画\"是习惯,用一般现在时 paint。✓ I paint a lot of pictures. am painting 是此刻正在。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp2','choice','{"stem":"\"I ___ breakfast now.\"(此刻正在:现在进行时)","options":["am having","had","will have","have"],"answer_index":0,"stem_cn":"我正在吃早饭。","explanation_cn":"\"此刻正在吃早饭\"用现在进行时 am having。✓ I am having breakfast now."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp2','choice','{"stem":"\"Do you always ___ up so late?\"(经常:一般现在时)","options":["got","getting","are getting","get"],"answer_index":3,"stem_cn":"你总是起这么晚吗?","explanation_cn":"always(总是)表示经常,用一般现在时 get。✓ Do you always get up so late?"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp2','choice','{"stem":"\"此刻正在做\"用现在进行时;\"经常/习惯做\"用:","options":["一般现在时","一般过去时","过去进行时","一般将来时"],"answer_index":0,"explanation_cn":"\"此刻正在做\"用现在进行时;\"经常/习惯做\"用一般现在时。✓ I am reading now(此刻)/ I read every day(经常)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp3','choice','{"stem":"\"The earth ___ round the sun.\"(客观真理:一般现在时)","options":["went","goes","is going","will go"],"answer_index":1,"stem_cn":"地球绕着太阳转。","explanation_cn":"\"地球绕太阳转\"是客观真理,用一般现在时 goes。✓ The earth goes round the sun."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp3','choice','{"stem":"\"The sun ___ in the east.\"(客观真理)","options":["will rise","is rising","rose","rises"],"answer_index":3,"stem_cn":"太阳从东方升起。","explanation_cn":"\"太阳从东方升起\"是客观真理,用一般现在时 rises。✓ The sun rises in the east."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp4','choice','{"stem":"主语是第三人称单数(he/she/it)时,一般现在时的动词要:","options":["不变","加 -s / -es","加 -ing","加 -ed"],"answer_index":1,"explanation_cn":"主语是第三人称单数(he/she/it)时,一般现在时动词末尾加 -s 或 -es。✓ She tells / He goes."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp4','choice','{"stem":"\"She always ___ me the truth.\"(她总是…真相:第三人称单数)","options":["telling","tell","tells","told"],"answer_index":2,"stem_cn":"她总是告诉我真相。","explanation_cn":"主语 She 是第三人称单数,动词 tell 加 -s 变 tells。✓ She always tells me the truth."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp4','choice','{"stem":"\"My sister ___ modern art.\"(我妹妹…现代艺术:第三人称单数)","options":["appreciates","appreciate","appreciated","is appreciating"],"answer_index":0,"stem_cn":"我妹妹欣赏现代艺术。","explanation_cn":"主语 My sister 是第三人称单数,appreciate 加 -s 变 appreciates。✓ My sister appreciates modern art."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp5','choice','{"stem":"\"I ___ this book is very interesting.\"(表''认为'',状态动词不用进行时)","options":["am thinking","think","thought","will think"],"answer_index":1,"stem_cn":"我认为这本书很有趣。","explanation_cn":"think 表\"认为\"是状态动词,用一般现在时,不用进行时。✓ I think this book is very interesting."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp5','choice','{"stem":"\"I ___ what you mean.\"(表''明白'',状态动词不用进行时)","options":["understand","am understanding","understood","will understand"],"answer_index":0,"stem_cn":"我明白你的意思。","explanation_cn":"understand(明白)是状态动词,用一般现在时,不说 am understanding。✓ I understand what you mean."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp5','choice','{"stem":"\"She ___ this song.\"(表''喜欢'',不用进行时)","options":["is liking","likes","will like","liked"],"answer_index":1,"stem_cn":"她喜欢这首歌。","explanation_cn":"like(喜欢)是状态动词,不用进行时;主语 She 第三人称单数加 -s 变 likes。✓ She likes this song."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp6','choice','{"stem":"\"I ___ you like classical music.\"(表''听说'',一般现在时)","options":["heard","will hear","hear","am hearing"],"answer_index":2,"stem_cn":"我听说你喜欢古典音乐。","explanation_cn":"hear 表\"听说\"时用一般现在时,不用进行时。✓ I hear you like classical music 我听说你喜欢古典音乐。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp6','choice','{"stem":"\"Water ___ at 0°C.\"(客观真理:水在0℃结冰)","options":["will freeze","froze","is freezing","freezes"],"answer_index":3,"stem_cn":"水在 0℃ 时结冰。","explanation_cn":"\"水在0℃结冰\"是客观真理,用一般现在时;water 第三人称单数加 -s 变 freezes。✓ Water freezes at 0°C."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp7','choice','{"stem":"\"She tells me ___ my pictures are good.\"(是否)","options":["whether","what","that","which"],"answer_index":0,"stem_cn":"她告诉我我的画好不好。","explanation_cn":"\"告诉我画好不好\"= 是否,用 whether 引导。✓ She tells me whether my pictures are good."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp7','choice','{"stem":"whether 引导宾语从句时,意思是:","options":["虽然","因为","是否","如果不"],"answer_index":2,"explanation_cn":"whether 引导宾语从句时意思是\"是否\"。✓ I don''t know whether he will come 我不知道他是否会来。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',5,'am2_l26_gp8','choice','{"stem":"\"It''s a new ___.\"(代替前面的名词 picture,避免重复)","options":["one","this","it","that"],"answer_index":0,"stem_cn":"这是一幅新的。","explanation_cn":"为避免重复前面的 picture,用 one 代替。✓ It''s a new one(= a new picture)。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',6,NULL,'choice','{"stem":"美语里\"窗帘\"也常说:","options":["curtains","drapes","wall cover","window cloth"],"answer_index":1,"explanation_cn":"美语里(厚)窗帘也常说 drapes;英式/通用说 curtains。✓ close the drapes 拉上窗帘。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',6,NULL,'choice','{"stem":"upside down 的意思是:","options":["正面朝上","里外反了","上下颠倒","从左到右"],"answer_index":2,"explanation_cn":"upside down = 上下颠倒、倒着。✓ isn''t it upside down? 是不是挂倒了?\n顺带记:正面朝上 = right side up;里外反了 = inside out;从左到右 = left to right."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',6,NULL,'choice','{"stem":"appreciate 的意思是:","options":["假装","欣赏,鉴赏","讨厌","忽视"],"answer_index":1,"explanation_cn":"appreciate = 欣赏、鉴赏。✓ appreciate modern art 欣赏现代艺术。\n顺带记:讨厌 = dislike;假装 = pretend;忽视 = ignore."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',6,NULL,'choice','{"stem":"whether 的意思是:","options":["是否","尽管","因为","所以"],"answer_index":0,"explanation_cn":"whether = 是否。✓ whether it is good 好还是不好。\n顺带记:因为 = because;尽管 = although;所以 = so."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',6,NULL,'choice','{"stem":"pretend 的意思是:","options":["证明","假设成立","推迟","假装"],"answer_index":3,"explanation_cn":"pretend = 假装。✓ pretend to understand 假装懂。\n顺带记:证明 = prove;假设成立 = suppose;推迟 = postpone."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',6,NULL,'choice','{"stem":"notice 的意思是:","options":["注意到","无视","记住","通知"],"answer_index":0,"explanation_cn":"notice = 注意到、察觉。✓ They notice more 他们观察到的更多。\n顺带记:无视 = ignore;通知 = inform;记住 = remember."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',7,NULL,'cloze','{"stem":"第 1 空","context":"I am an art student, and I ___1___ a lot of pictures. Many people ___2___ that they understand modern art. The sun ___3___ in the east every morning. My little sister ___4___ what a good picture is.","blank_no":1,"options":["paint","am painting","painted","will paint"],"answer_index":0,"explanation_cn":"\"我经常画画\"是习惯,用一般现在时 paint。✓ I paint a lot of pictures.\n✗ am painting:am painting 是此刻正在,不是\"经常\";✗ painted:painted 是过去;✗ will paint:will paint 是将来."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',7,NULL,'cloze','{"stem":"第 2 空","context":"I am an art student, and I ___1___ a lot of pictures. Many people ___2___ that they understand modern art. The sun ___3___ in the east every morning. My little sister ___4___ what a good picture is.","blank_no":2,"options":["pretend","are pretending","pretended","will pretend"],"answer_index":0,"explanation_cn":"\"很多人经常装懂\"是习惯,主语 people 复数,用一般现在时 pretend。✓ Many people pretend they understand art.\n✗ are pretending:说的是经常,不是此刻正在;✗ pretended:pretended 是过去;✗ will pretend:will pretend 是将来."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',7,NULL,'cloze','{"stem":"第 3 空","context":"I am an art student, and I ___1___ a lot of pictures. Many people ___2___ that they understand modern art. The sun ___3___ in the east every morning. My little sister ___4___ what a good picture is.","blank_no":3,"options":["rises","is rising","rose","will rise"],"answer_index":0,"explanation_cn":"\"太阳每天从东方升起\"是客观真理,用一般现在时;sun 第三人称单数加 -s 变 rises。✓ The sun rises in the east.\n✗ is rising:客观真理不用进行时;✗ rose:rose 是过去;✗ will rise:客观真理不用将来."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',7,NULL,'cloze','{"stem":"第 4 空","context":"I am an art student, and I ___1___ a lot of pictures. Many people ___2___ that they understand modern art. The sun ___3___ in the east every morning. My little sister ___4___ what a good picture is.","blank_no":4,"options":["knows","is knowing","knew","will know"],"answer_index":0,"explanation_cn":"know 是状态动词,用一般现在时;sister 第三人称单数加 -s 变 knows。✓ My sister knows what a good picture is.\n✗ is knowing:know 是状态动词,不用进行时;✗ knew:knew 是过去;✗ will know:说的是一贯如此,不用将来."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',8,NULL,'choice','{"stem":"What does the writer do?","options":["He is a music teacher","He sells curtains","He is a famous critic","He is an art student who paints pictures"],"answer_index":3,"explanation_cn":"课文说 I am an art student, and I paint a lot of pictures,作者是学美术的、经常画画。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',8,NULL,'choice','{"stem":"Who does the writer think appreciates modern art best?","options":["Young children","Art teachers","Rich collectors","Museum guides"],"answer_index":0,"explanation_cn":"课文说 young children often appreciate modern pictures better than anyone else,作者觉得小孩子最会欣赏。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',8,NULL,'choice','{"stem":"What was wrong with the picture on the wall?","options":["It was too small","It was the wrong color","It was hung upside down","It was torn"],"answer_index":2,"explanation_cn":"课文结尾妹妹发现画挂倒了(upside down),作者一看果然如此。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',9,NULL,'choice','{"stem":"你想说\"地球围绕太阳转\"(客观真理用一般现在时):","options":["The earth goes round the sun.","The earth went round the sun.","The earth go round the sun.","The earth is going round the sun."],"answer_index":0,"explanation_cn":"客观真理用一般现在时;earth 第三人称单数,go 加 -es 变 goes。✓ The earth goes round the sun. 场合:说一个众所周知的事实。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',9,NULL,'choice','{"stem":"你想说\"我明白你的意思\"(understand 这类词不用进行时):","options":["I understood what you mean now.","I understands what you mean.","I understand what you mean.","I am understanding what you mean."],"answer_index":2,"explanation_cn":"understand 表\"明白\",用一般现在时,不用进行时。✓ I understand what you mean. 场合:表示自己听懂了。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',9,NULL,'choice','{"stem":"你想说\"她每天七点起床\"(习惯用一般现在时):","options":["She is getting up at seven every day.","She gets up at seven every day.","She get up at seven every day.","She got up at seven every day."],"answer_index":1,"explanation_cn":"\"每天七点起床\"是习惯,用一般现在时;She 第三人称单数,get 加 -s 变 gets。✓ She gets up at seven every day. 场合:说别人的日常习惯。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"appreciate 的意思是:","options":["购买","假装","贬低","欣赏,鉴赏"],"answer_index":3,"explanation_cn":"appreciate = 欣赏、鉴赏。✓ appreciate art 欣赏艺术。\n顺带记:贬低 = look down on;假装 = pretend;购买 = buy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"pretend 的意思是:","options":["假装","预防","承认","延长"],"answer_index":0,"explanation_cn":"pretend = 假装。✓ pretend to understand 假装懂。\n顺带记:承认 = admit;预防 = prevent;延长 = extend."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"\"Water ___ at 100°C.\"(客观真理:水100℃沸腾)","options":["is boiling","boiled","will boil","boils"],"answer_index":3,"stem_cn":"水在 100℃ 时沸腾。","explanation_cn":"\"水在100℃沸腾\"是客观真理,用一般现在时;water 第三人称单数加 -s 变 boils。✓ Water boils at 100°C."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"\"I ___ you are right.\"(表''认为'',一般现在时)","options":["think","will think","am thinking","thought"],"answer_index":0,"stem_cn":"我认为你是对的。","explanation_cn":"think 表\"认为\"时用一般现在时,不用进行时。✓ I think you are right."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"\"Isn''t it upside down?\" 这句话的意思是:","options":["它是不是很贵?","它是不是太大了?","它是不是挂倒了?","它是不是旧的?"],"answer_index":2,"explanation_cn":"Isn''t it upside down? 意思是\"它是不是挂倒了(上下颠倒了)?\"。upside down = 上下颠倒。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"\"She looked at it critically.\" 这句话的意思是:","options":["她用挑剔的目光看它。","她根本没看。","她赞叹地看着它。","她随便看了一眼。"],"answer_index":0,"explanation_cn":"She looked at it critically. 意思是\"她用挑剔、批评的目光看它\"。critically = 挑剔地。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"Why does the writer think children are the best art critics?","options":["They paint faster","They buy more art","They study art in school","They notice more and appreciate pictures better"],"answer_index":3,"passage":"I am an art student, and I paint a lot of pictures. Many people pretend that they understand modern art. They always tell you what a picture is ''about''. Of course, many pictures are not ''about'' anything. They are just pretty patterns. We like them in the same way that we like pretty curtain material. I think that young children often appreciate modern pictures better than anyone else. They notice more. My sister is only seven, but she always tells me whether my pictures are good or not. She came into my room yesterday. ''What are you doing?'' she asked. ''I''m hanging this picture on the wall,'' I answered. ''It''s a new one. Do you like it?'' She looked at it critically for a moment. ''It''s all right,'' she said, ''but isn''t it upside down?'' I looked at it again. She was right! It was!","explanation_cn":"课文说小孩子 notice more、更能欣赏现代画,所以是最好的评论家。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"What did the sister say about the new picture?","options":["''It''s the best ever.''","''It''s all right, but isn''t it upside down?''","''It''s terrible.''","''Sell it now.''"],"answer_index":1,"passage":"I am an art student, and I paint a lot of pictures. Many people pretend that they understand modern art. They always tell you what a picture is ''about''. Of course, many pictures are not ''about'' anything. They are just pretty patterns. We like them in the same way that we like pretty curtain material. I think that young children often appreciate modern pictures better than anyone else. They notice more. My sister is only seven, but she always tells me whether my pictures are good or not. She came into my room yesterday. ''What are you doing?'' she asked. ''I''m hanging this picture on the wall,'' I answered. ''It''s a new one. Do you like it?'' She looked at it critically for a moment. ''It''s all right,'' she said, ''but isn''t it upside down?'' I looked at it again. She was right! It was!","explanation_cn":"妹妹看了画说 ''It''s all right, but isn''t it upside down?''(还行,不过是不是挂倒了?)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"Who is the student''s best critic?","options":["A gallery owner","His father","His teacher","His seven-year-old sister"],"answer_index":3,"audio":"I am an art student, and I paint a lot of pictures. Many people pretend that they understand modern art. They always tell you what a picture is ''about''. Of course, many pictures are not ''about'' anything. They are just pretty patterns. We like them in the same way that we like pretty curtain material. I think that young children often appreciate modern pictures better than anyone else. They notice more. My sister is only seven, but she always tells me whether my pictures are good or not. She came into my room yesterday. ''What are you doing?'' she asked. ''I''m hanging this picture on the wall,'' I answered. ''It''s a new one. Do you like it?'' She looked at it critically for a moment. ''It''s all right,'' she said, ''but isn''t it upside down?'' I looked at it again. She was right! It was!","explanation_cn":"课文说七岁的妹妹总能说出画好不好,是作者最好的评论家。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l26',10,NULL,'choice','{"stem":"Was the sister right about the picture?","options":["Yes, it was upside down","Yes, it was too big","No, it was too dark","No, it was fine"],"answer_index":0,"audio":"I am an art student, and I paint a lot of pictures. Many people pretend that they understand modern art. They always tell you what a picture is ''about''. Of course, many pictures are not ''about'' anything. They are just pretty patterns. We like them in the same way that we like pretty curtain material. I think that young children often appreciate modern pictures better than anyone else. They notice more. My sister is only seven, but she always tells me whether my pictures are good or not. She came into my room yesterday. ''What are you doing?'' she asked. ''I''m hanging this picture on the wall,'' I answered. ''It''s a new one. Do you like it?'' She looked at it critically for a moment. ''It''s all right,'' she said, ''but isn''t it upside down?'' I looked at it again. She was right! It was!","explanation_cn":"课文结尾作者再看一眼,发现妹妹说对了,画确实挂倒了。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l27',2,4,27,'A wet night','雨夜','一般过去时(主考:表过去某时发生并已结束的动作 · 规则动词词尾加 -ed · 不规则动词过去式单独记 told/sang/felt/woke/crept/slept/wound/found · 否定 did not + 原形 · 疑问 Did + 主语 + 原形 · 过去时间标志 yesterday/ago/last night)+ as soon as 引导时间状语从句 / so 连接结果(辅考)','傍晚男孩们在田野中央搭起帐篷,篝火做饭、讲故事唱歌;后来下起雨,他们熄火钻进睡袋睡得正香。半夜两人惊醒——帐篷里灌满了水!原来雨下得大,田里形成一条小溪,正好从帐篷底下流过。','{"q":"Listen and answer — What happened to the boys in the night?","options":["Their tent was full of water","They saw a wild animal","They lost their way","Their fire went out"],"answer_index":0}'::jsonb,'{"title":"说''过去发生的事''(一般过去时)","intro":"本课讲一般过去时——表示过去某个时候发生并已经结束的动作。规则动词词尾加 -ed;很多常用动词是不规则的,要单独记。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["表过去发生并结束:一般过去时","They cooked a meal over an open fire."],["规则动词:词尾加 -ed","They hurried outside. / A stream formed."],["不规则动词:单独记","tell→told, sing→sang, feel→felt, wake→woke"],["否定 / 疑问:did not / Did …","Did they cook a meal? / They did not stay inside."]]},"specialRules":[{"rule":"as soon as = ''一……就……'',引导时间从句:As soon as this was done, they cooked a meal.","mark":"as soon as 一…就…"},{"rule":"so = ''所以/因此'',连接结果:The boys felt tired, so they put out the fire.","mark":"so 因此"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',1,NULL,'Late in the afternoon, the boys put up their tent in the middle of a field.','傍晚时分,孩子们在田野中央搭起了帐篷。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',2,NULL,'As soon as this was done, they cooked a meal over an open fire.','这件事刚一做完,他们就在篝火上做起了饭。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',3,NULL,'They were all hungry and the food smelled good.','他们全都饿了,饭菜散发出阵阵香味。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',4,NULL,'After a wonderful meal, they told stories and sang songs by the campfire.','美美地吃了一顿饭后,他们就围着篝火讲起了故事、唱起了歌。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',5,NULL,'But some time later it began to rain. The boys felt tired so they put out the fire and crept into their tent.','但过了一阵子,天下起雨来。孩子们感到累了,于是熄灭了篝火,钻进了帐篷。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',6,NULL,'Their sleeping bags were warm and comfortable, so they all slept soundly.','睡袋既暖和又舒服,因此他们都睡得很香。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',7,NULL,'In the middle of the night, two boys woke up and began shouting. The tent was full of water!','半夜里,有两个孩子醒了,大声叫了起来。原来帐篷里到处都是水!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',8,NULL,'They all leapt out of their sleeping bags and hurried outside.','他们全都跳出睡袋,匆忙跑到外面。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',9,NULL,'It was raining heavily and they found that a stream had formed in the field.','雨下得很大,他们发现地上已经形成了一条小溪。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l27',10,NULL,'The stream wound its way across the field and then flowed right under their tent!','那小溪弯弯曲曲穿过田野,然后正好从他们的帐篷底下流过!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
