INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l28','put up','',NULL,'/pʊt ʌp/','He has put up ''No Parking'' signs.','他张贴了''禁止停车''的牌子。','They put up a new sign.','他们挂了一块新牌子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l28','ever since','',NULL,'/ˈevər sɪns/','Ever since he moved in, he has had trouble.','自从他搬进来,就一直有麻烦。','I''ve liked music ever since then.','从那以后我就一直喜欢音乐。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l28','be able to','',NULL,'/bi ˈeɪbl tə/','He has not been able to get his car in.','他一直没能把车开进去。','I am able to help you.','我能帮你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l28','one of the + 最高级','',NULL,'/wʌn əv ðə/','It is one of the ugliest faces I have ever seen.','这是我见过的最丑的脸之一。','She is one of the best students.','她是最优秀的学生之一。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp1','choice','{"stem":"\"He ___ just bought a new house.\"(现在完成时,主语单数)","options":["have","is","has","did"],"answer_index":2,"stem_cn":"他刚买了一所新房子。","explanation_cn":"现在完成时 = have/has + 过去分词;主语 He 单数用 has。✓ He has just bought a new house."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp1','choice','{"stem":"\"The signs ___ not had any effect.\"(现在完成时,主语复数)","options":["have","has","are","did"],"answer_index":0,"stem_cn":"这些牌子没起任何作用。","explanation_cn":"现在完成时主语复数用 have + 过去分词。✓ The signs have not had any effect."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp1','choice','{"stem":"\"He hasn''t found a parking spot ___.\"(否定句尾''还没'':用于现在完成)","options":["ever","yet","already","since"],"answer_index":1,"stem_cn":"他还没找到停车位。","explanation_cn":"yet 用于否定/疑问句尾,表\"还(没)\",常配现在完成时。✓ He hasn''t found a parking spot yet."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp2','choice','{"stem":"\"I have not seen him ___ 1994.\"(接过去的时间点:自从)","options":["for","at","in","since"],"answer_index":3,"stem_cn":"自从1994年以来我没见过他。","explanation_cn":"since 接过去的时间点,表\"自从…以来\",配现在完成时。✓ I have not seen him since 1994."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp2','choice','{"stem":"\"She has lived here ___ she was a child.\"(接从句:自从…以来)","options":["during","since","when","for"],"answer_index":1,"stem_cn":"她从小就住在这里。","explanation_cn":"since 也可以接从句,表\"自从…以来\"。✓ She has lived here since she was a child."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp3','choice','{"stem":"\"Tim has been abroad ___ three years.\"(接一段时间:达三年)","options":["in","since","for","during"],"answer_index":2,"stem_cn":"蒂姆出国已三年了。","explanation_cn":"for 接一段时间,表\"持续多久\"。✓ Tim has been abroad for three years."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp3','choice','{"stem":"\"They ___ in this city for five years.\"(住了五年:现在完成)","options":["are living","have lived","lived","live"],"answer_index":1,"stem_cn":"他们在这座城市住了五年了。","explanation_cn":"\"住了五年(到现在)\"用现在完成时;主语 They 用 have + lived。✓ They have lived in this city for five years."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp4','choice','{"stem":"\"___, he has won five prizes.\"(至今为止)","options":["Up till now","Long ago","Next year","Yesterday"],"answer_index":0,"stem_cn":"至今为止,他已得了五个奖。","explanation_cn":"up till now = 至今为止,常配现在完成时。✓ Up till now, he has won five prizes."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp4','choice','{"stem":"\"I have been to New York three times ___.\"(迄今、到目前为止)","options":["then","ago","last year","so far"],"answer_index":3,"stem_cn":"迄今我已去过纽约三次。","explanation_cn":"so far = 到目前为止、迄今,常配现在完成时。✓ I have been to New York three times so far."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp5','choice','{"stem":"\"It is one of the ugliest faces I have ___ seen.\"(表''曾经'',放助动词和过去分词之间)","options":["ago","since","ever","yet"],"answer_index":2,"stem_cn":"这是我见过的最丑的脸之一。","explanation_cn":"ever 表\"曾经\",放在助动词 have 和过去分词之间。✓ It is one of the ugliest faces I have ever seen."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp5','choice','{"stem":"\"He has ___ bought a new house.\"(表''刚刚'',放中间)","options":["just","since","ago","yet"],"answer_index":0,"stem_cn":"他刚买了一所新房子。","explanation_cn":"just 表\"刚刚\",放在 have/has 和过去分词之间。✓ He has just bought a new house."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp5','choice','{"stem":"\"I have ___ finished my homework.\"(表''已经'',放中间)","options":["since","already","ever","yet"],"answer_index":1,"stem_cn":"我已经写完作业了。","explanation_cn":"already 表\"已经\",放在 have 和过去分词之间。✓ I have already finished my homework."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp6','choice','{"stem":"\"I have ___ to New York twice.\"(去过又回来了)","options":["went","gone","been","being"],"answer_index":2,"stem_cn":"我去过纽约两次。","explanation_cn":"have been to = 去过某地(已经回来了)。✓ I have been to New York twice."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp6','choice','{"stem":"\"He isn''t here; he has ___ to the store.\"(去了还没回来)","options":["being","been","went","gone"],"answer_index":3,"stem_cn":"他不在;他去商店了。","explanation_cn":"have gone to = 去了某地(还没回来)。✓ He isn''t here; he has gone to the store."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp7','choice','{"stem":"\"The people ___ believe in myths are rare.\"(指人,作主语)","options":["which","who","whose","where"],"answer_index":1,"stem_cn":"相信神话的人很少见。","explanation_cn":"who 引导定语从句,指人,这里在从句里作主语。✓ The people who believe in myths are rare."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp7','choice','{"stem":"\"This is the hotel ___ was built last year.\"(指物,作主语)","options":["which","who","whose","whom"],"answer_index":0,"stem_cn":"这就是去年建的那家酒店。","explanation_cn":"which 引导定语从句,指物,这里在从句里作主语。✓ This is the hotel which was built last year."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp8','choice','{"stem":"\"The pilot ___ plane landed safely was not hurt.\"(表''那个人的'',所属)","options":["whom","which","who","whose"],"answer_index":3,"stem_cn":"那位飞机安全着陆的飞行员没有受伤。","explanation_cn":"whose 表\"那个人的\",引导定语从句表所属。✓ The pilot whose plane landed safely was not hurt."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',5,'am2_l28_gp8','choice','{"stem":"\"The man ___ you met yesterday is an actor.\"(指人,作宾语)","options":["where","whom","whose","which"],"answer_index":1,"stem_cn":"你昨天遇见的那个人是演员。","explanation_cn":"whom 引导定语从句,指人,在从句里作宾语。✓ The man whom you met yesterday is an actor."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',6,NULL,'choice','{"stem":"美语里\"停车场\"常说:","options":["stop yard","parking lot","car park","parking place"],"answer_index":1,"explanation_cn":"美语\"停车场\"说 parking lot;英式说 car park。✓ park in the parking lot 停在停车场。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',6,NULL,'choice','{"stem":"美语里 get 的过去分词(have ___)常用:","options":["gat","got","gotten","getted"],"answer_index":2,"explanation_cn":"美语里 get 的过去分词常用 gotten;英式用 got。✓ He has gotten a new car 他弄到了一辆新车。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',6,NULL,'choice','{"stem":"rare 的意思是:","options":["巨大的","罕见的,稀有的","常见的","便宜的"],"answer_index":1,"explanation_cn":"rare = 罕见的、稀有的。✓ one of those rare people 少有的那种人之一。\n顺带记:常见的 = common;昂贵的 = expensive;巨大的 = huge."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',6,NULL,'choice','{"stem":"ancient 的意思是:","options":["未来的","现代的","短暂的","古代的,古老的"],"answer_index":3,"explanation_cn":"ancient = 古代的、古老的。✓ ancient myths 古代神话。\n顺带记:现代的 = modern;未来的 = future;短暂的 = brief."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',6,NULL,'choice','{"stem":"trouble 的意思是:","options":["乐趣","休息","麻烦,难题","礼物"],"answer_index":2,"explanation_cn":"trouble = 麻烦、难题。✓ trouble with cars 和汽车有关的麻烦。\n顺带记:乐趣 = fun;礼物 = gift;休息 = rest."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',6,NULL,'choice','{"stem":"effect 的意思是:","options":["原因","结果,效果","错误","开始"],"answer_index":1,"explanation_cn":"effect = 结果、效果。✓ have no effect 没有效果。\n顺带记:原因 = cause;错误 = mistake;开始 = beginning."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',7,NULL,'cloze','{"stem":"第 1 空","context":"Jasper ___1___ just bought a new house. Ever since he moved in, he ___2___ trouble with cars and their owners. He ___3___ not been able to park his own car even once. The ''No Parking'' signs ___4___ not had any effect.","blank_no":1,"options":["has","have","is","did"],"answer_index":0,"explanation_cn":"\"刚买了房子\"到现在,用现在完成时;主语 Jasper 单数用 has + 过去分词。✓ Jasper has just bought a new house.\n✗ have:主语单数用 has 不用 have;✗ is:be 动词不能构成现在完成时;✗ did:did 是一般过去,不是现在完成."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',7,NULL,'cloze','{"stem":"第 2 空","context":"Jasper ___1___ just bought a new house. Ever since he moved in, he ___2___ trouble with cars and their owners. He ___3___ not been able to park his own car even once. The ''No Parking'' signs ___4___ not had any effect.","blank_no":2,"options":["has had","have had","had","is having"],"answer_index":0,"explanation_cn":"\"一直有麻烦\"到现在,用现在完成时 has + had(have 的过去分词)。✓ He has had trouble with cars.\n✗ have had:主语 he 单数用 has;✗ had:光 had 是一般过去,没体现\"到现在\";✗ is having:进行时表此刻,不表\"一直到现在\"."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',7,NULL,'cloze','{"stem":"第 3 空","context":"Jasper ___1___ just bought a new house. Ever since he moved in, he ___2___ trouble with cars and their owners. He ___3___ not been able to park his own car even once. The ''No Parking'' signs ___4___ not had any effect.","blank_no":3,"options":["has","have","was","did"],"answer_index":0,"explanation_cn":"\"一直没能\"到现在,用现在完成时;后接 not been able。✓ He has not been able to park his own car.\n✗ have:主语 he 单数用 has;✗ was:一般过去,不是现在完成;✗ did:did 不构成现在完成."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',7,NULL,'cloze','{"stem":"第 4 空","context":"Jasper ___1___ just bought a new house. Ever since he moved in, he ___2___ trouble with cars and their owners. He ___3___ not been able to park his own car even once. The ''No Parking'' signs ___4___ not had any effect.","blank_no":4,"options":["have","has","was","did"],"answer_index":0,"explanation_cn":"\"牌子一直没起作用\"到现在,用现在完成时;主语 signs 复数用 have + 过去分词。✓ The signs have not had any effect.\n✗ has:主语复数用 have;✗ was:一般过去且单复数不对;✗ did:did 不构成现在完成."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',8,NULL,'choice','{"stem":"What has Jasper White just done?","options":["He has bought a new house in the city","He has built a new garage","He has moved to the countryside","He has sold his old car"],"answer_index":0,"explanation_cn":"课文说 He has just bought a new house in the city,贾斯珀刚在城里买了新房。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',8,NULL,'choice','{"stem":"Why can''t Jasper get his car into his garage?","options":["He has lost his keys","His garage is too small","His car is broken","Someone always parks a car outside his gate"],"answer_index":3,"explanation_cn":"课文说 someone has parked a car outside his gate,总有人把车停在他大门外,所以他的车开不进去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',8,NULL,'choice','{"stem":"What has Jasper put over his gate?","options":["A new ''No Parking'' sign","A security camera","An ugly stone head of Medusa","A bright light"],"answer_index":2,"explanation_cn":"课文说 he has put an ugly stone head over the gate,那是美杜莎的头像。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',9,NULL,'choice','{"stem":"你想说\"我从1994年就没见过他了\"(自从某时间点用 since + 现在完成时):","options":["I haven''t seen him since 1994.","I don''t see him since 1994.","I didn''t see him since 1994.","I haven''t seen him for 1994."],"answer_index":0,"explanation_cn":"\"自从某个时间点\"用 since + 现在完成时。✓ I haven''t seen him since 1994. 场合:说从某个时间起一直没做某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',9,NULL,'choice','{"stem":"你想说\"他们相识十年了\"(持续一段时间用 for + 现在完成时):","options":["They know each other for ten years.","They have known each other since ten years.","They have known each other for ten years.","They knew each other for ten years."],"answer_index":2,"explanation_cn":"\"持续了一段时间\"用 for + 现在完成时。✓ They have known each other for ten years. 场合:说某状态持续了多久。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',9,NULL,'choice','{"stem":"你想说\"你去过纽约吗?\"(问经历用 Have you been to):","options":["Have you ever go to New York?","Did you been to New York?","Have you gone to New York?","Have you been to New York?"],"answer_index":3,"explanation_cn":"问\"去过没有(经历)\"用 Have you been to…?。✓ Have you been to New York? 场合:问对方有没有去过某地。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"myth 的意思是:","options":["一首诗","科学理论","历史事实","神话故事"],"answer_index":3,"explanation_cn":"myth = 神话故事。✓ ancient myths 古代神话。\n顺带记:历史事实 = historical fact;科学理论 = scientific theory;一首诗 = a poem."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"effect 的意思是:","options":["计划","结果,效果","原因","错误"],"answer_index":1,"explanation_cn":"effect = 结果、效果。✓ have no effect 没起作用。\n顺带记:原因 = cause;计划 = plan;错误 = mistake."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"\"I have ___ seen such an ugly face.\"(表''从未'',放中间)","options":["never","yet","already","ever"],"answer_index":0,"stem_cn":"我从没见过这么丑的脸。","explanation_cn":"never 表\"从未\",放在 have 和过去分词之间。✓ I have never seen such an ugly face."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"\"He is the man ___ car was stolen.\"(表''那个人的'':所属)","options":["which","whom","whose","who"],"answer_index":2,"stem_cn":"他就是那个车被偷的人。","explanation_cn":"whose 表\"那个人的\",引导定语从句表所属。✓ He is the man whose car was stolen."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"\"He has not been able to get his car in.\" 这句话的意思是:","options":["他一直没能把车开进去。","他不想把车开进去。","他正在把车开进去。","他把车开出去了。"],"answer_index":0,"explanation_cn":"He has not been able to get his car in. 意思是\"他一直没能把车开进去\"。been able to = 能够。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"\"These signs have not had any effect.\" 这句话的意思是:","options":["这些牌子被拿走了。","这些牌子很有用。","这些牌子是新的。","这些牌子没起任何作用。"],"answer_index":3,"explanation_cn":"These signs have not had any effect. 意思是\"这些牌子没起任何作用\"。have an effect = 起作用。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"Why has Jasper put a stone head over his gate?","options":["It was a gift from a friend","It keeps the rain off","He hopes it will turn cars and their owners to stone","He thinks it looks beautiful"],"answer_index":2,"passage":"Jasper White is one of those rare people who believes in ancient myths. He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners. When he returns home at night, he always finds that someone has parked a car outside his gate. Because of this, he has not been able to get his own car into his garage even once. Jasper has put up ''No Parking'' signs outside his gate, but these have not had any effect. Now he has put an ugly stone head over the gate. It is one of the ugliest faces I have ever seen. I asked him what it was and he told me that it was Medusa, the Gorgon. Jasper hopes that she will turn cars and their owners to stone. But none of them has been turned to stone yet!","explanation_cn":"课文说 Jasper hopes that she will turn cars and their owners to stone,他盼着石像把车和车主变成石头。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"Have the ''No Parking'' signs worked?","options":["Yes, but only at night","No, they have not had any effect","Yes, no one parks there now","No, they were stolen"],"answer_index":1,"passage":"Jasper White is one of those rare people who believes in ancient myths. He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners. When he returns home at night, he always finds that someone has parked a car outside his gate. Because of this, he has not been able to get his own car into his garage even once. Jasper has put up ''No Parking'' signs outside his gate, but these have not had any effect. Now he has put an ugly stone head over the gate. It is one of the ugliest faces I have ever seen. I asked him what it was and he told me that it was Medusa, the Gorgon. Jasper hopes that she will turn cars and their owners to stone. But none of them has been turned to stone yet!","explanation_cn":"课文说 these have not had any effect,那些\"禁止停车\"的牌子毫无效果。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"What is Jasper White''s problem?","options":["People keep parking cars outside his gate","His neighbors are too noisy","He can''t afford a new car","He has lost his house"],"answer_index":0,"audio":"Jasper White is one of those rare people who believes in ancient myths. He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners. When he returns home at night, he always finds that someone has parked a car outside his gate. Because of this, he has not been able to get his own car into his garage even once. Jasper has put up ''No Parking'' signs outside his gate, but these have not had any effect. Now he has put an ugly stone head over the gate. It is one of the ugliest faces I have ever seen. I asked him what it was and he told me that it was Medusa, the Gorgon. Jasper hopes that she will turn cars and their owners to stone. But none of them has been turned to stone yet!","explanation_cn":"课文讲总有人把车停在他大门外,他自己的车开不进车库,这就是他的烦恼。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l28',10,NULL,'choice','{"stem":"Has anyone been turned to stone yet?","options":["No, but the cars have","No, no one has been turned to stone yet","Yes, several car owners have","Yes, one car was"],"answer_index":1,"audio":"Jasper White is one of those rare people who believes in ancient myths. He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners. When he returns home at night, he always finds that someone has parked a car outside his gate. Because of this, he has not been able to get his own car into his garage even once. Jasper has put up ''No Parking'' signs outside his gate, but these have not had any effect. Now he has put an ugly stone head over the gate. It is one of the ugliest faces I have ever seen. I asked him what it was and he told me that it was Medusa, the Gorgon. Jasper hopes that she will turn cars and their owners to stone. But none of them has been turned to stone yet!","explanation_cn":"课文结尾说 none of them has been turned to stone yet,至今还没一个变成石头。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l29',2,4,29,'Taxi!','出租汽车!','一般过去时 vs 现在完成时对比(主考:有明确过去时间 in 1994/ago/last month → 一般过去 · 与现在有联系 since/for/up till now/ever/before → 现在完成 · has/have + 过去分词)+ 定语从句 who / 表语从句 that(辅考)','本·弗西特机长买了一架小型瑞士飞机''皮勒特斯·波特''当''出租汽车'',能在雪地、水面甚至耕过的田里降落,已把乘客送到屋顶、废弃停车场等许多稀奇地方;但他刚拒绝了一位商人飞往大西洋孤岛罗卡尔的请求——因为那趟太危险了。','{"q":"Listen and answer — Does Captain Fawcett think any trip is too dangerous?","options":["Yes — he refused to fly to Rockall","No, he will fly anywhere","Only trips at night","Only trips over the sea"],"answer_index":0}'::jsonb,'{"title":"一般过去时 vs 现在完成时","intro":"本课对比两个时态:有明确的过去时间(in 1994 / ago / last month)用一般过去时;和现在有联系(since / for / up till now / ever)用现在完成时。全用本课句子举例。","table":{"headers":["用哪个时态","信号词 / 本课例子"],"rows":[["有明确过去时间 → 一般过去时","I saw him in 1994. / last month"],["自从…以来 → 现在完成时(since)","I have not seen him since 1994."],["持续一段时间 → 现在完成时(for)","I have not seen him for three years."],["至今 / 曾经 → 现在完成时(up till now / ever)","Have you ever stayed here?"]]},"specialRules":[{"rule":"ago(…以前)配一般过去;since/for 配现在完成:three years ago(过去)↔ for three years(现在完成)","mark":"ago vs for/since"},{"rule":"定语从句 who 指人:a doctor who flew…;表语从句 that:The surprising thing is that it can land anywhere.","mark":"who / that 从句"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',1,NULL,'Captain Ben Fawcett has bought an unusual taxi and has begun a new service.','本·弗西特机长买了一辆不同寻常的出租汽车,并开始了一项新业务。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',2,NULL,'The ''taxi'' is a small Swiss airplane called a ''Pilatus Porter''. This wonderful plane can carry seven passengers.','这辆''出租汽车''是一架小型瑞士飞机,叫''皮勒特斯·波特''号。这架奇妙的飞机可载7名乘客。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',3,NULL,'The most surprising thing about it, however, is that it can land anywhere: on snow, water, or even on a plowed field.','然而,最令人惊奇的是它能够在任何地方降落:雪地上、水面上,甚至刚耕过的田里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',4,NULL,'Captain Fawcett''s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains.','弗西特机长的第一名乘客是位医生,他从伯明翰飞往威尔士山区一个偏僻的村庄。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',5,NULL,'Since then, Captain Fawcett has flown passengers to many unusual places.','从那时起,弗西特机长已经载送乘客到过许多不寻常的地方。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',6,NULL,'Once he landed on the roof of an apartment building and on another occasion, he landed in a deserted parking lot.','一次,他把飞机降落在了一栋公寓楼的屋顶上;还有一次,降落在了一个废弃的停车场上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',7,NULL,'Captain Fawcett has just refused a strange request from a businessman.','弗西特机长刚刚拒绝了一位商人的奇特要求。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l29',8,NULL,'The man wanted to fly to Rockall, a lonely island in the Atlantic Ocean, but Captain Fawcett did not take him because the trip was too dangerous.','这个人想要飞往大西洋上的一个孤岛——罗卡尔岛,弗西特机长之所以不送他去,是因为那趟飞行太危险了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
