INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l30','bank','/bæŋk/','n','河岸;岸边','sat on the riverbank') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l30','strike','/straɪk/','v','撞;击中(struck)','The ball struck him so hard') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l30','realize','/ˈriːəlaɪz/','v','意识到,明白(美语拼写)','when he realized what had happened') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l30_gp1','am2_l30','some / any:肯定句用 some,否定疑问用 any',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
