INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l30','soccer','football','(踢的)足球;美语 soccer,英式 football(美语 football 指橄榄球)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l30','toward','towards','朝,向;美语常用 toward(不带 s),英式 towards') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
