INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l30','riverbank','river bank','河岸;美语常合写 riverbank,英式分写 river bank') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l30','cut across','',NULL,'/kʌt əˈkrɔːs/','The Wayle cuts across the park.','威尔河横穿公园。','A path cuts across the field.','一条小路横穿田野。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l30','call out to','',NULL,'/kɔːl aʊt tuː/','Some people called out to the man in the boat.','一些人对船上的人大声喊。','She called out to her friend across the street.','她隔着街对朋友喊。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l30','so ... that ...','',NULL,'/soʊ ... ðæt/','The ball struck him so hard that he nearly fell in.','球打得他那么重,他差点落水。','He was so tired that he fell asleep.','他累得睡着了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l30','run away','',NULL,'/rʌn əˈweɪ/','The children had all run away.','孩子们全跑光了。','The dog ran away last night.','那条狗昨晚跑走了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp1','choice','{"stem":"\"There were ___ people rowing on the river.\"(肯定句,表示\"一些\")","options":["any","a","some","much"],"answer_index":2,"stem_cn":"河上有一些人在划船。","explanation_cn":"肯定句里表示\"一些\"用 some。✓ There were some people rowing on the river 河上有些人在划船。✗ any 多用于否定和疑问;✗ much 修饰不可数;✗ a 只接单数。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp1','choice','{"stem":"\"There weren''t ___ children in sight.\"(否定句,表示\"任何\")","options":["much","any","one","some"],"answer_index":1,"stem_cn":"一个孩子也看不见了。","explanation_cn":"否定句(weren''t)里表示\"任何\"用 any。✓ There weren''t any children in sight 一个孩子也看不见。✗ some 一般不用于否定;✗ much 修饰不可数;✗ one 意思是\"一个\"。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp1','choice','{"stem":"\"Is there ___ milk in the bottle?\"(疑问句,表示\"任何\")","options":["the","a","some","any"],"answer_index":3,"stem_cn":"瓶子里有牛奶吗?","explanation_cn":"疑问句(Is there…?)里表示\"任何\"用 any。✓ Is there any milk in the bottle? 瓶里有牛奶吗?✗ some 多用于肯定句;✗ a 不接不可数 milk;✗ the 表特指,这里泛问。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp2','choice','{"stem":"\"___ Wayle cuts across the park near my home.\"(河流专名前加定冠词)","options":["One","A","The","An"],"answer_index":2,"stem_cn":"威尔河横穿我家附近的公园。","explanation_cn":"河流专名前要加定冠词。✓ The Wayle cuts across the park 威尔河横穿公园。✗ A/An 用于泛指单数,不用于河名;✗ One 意思是\"一条\",不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp2','choice','{"stem":"\"London is on ___ Thames.\"(河流名前加定冠词)","options":["the","an","a","one"],"answer_index":0,"stem_cn":"伦敦在泰晤士河畔。","explanation_cn":"河流名(the Thames)前加定冠词。✓ London is on the Thames 伦敦在泰晤士河畔。✗ a/an 不用于河名;✗ one 意思是\"一条\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp2','choice','{"stem":"\"Heyerdahl crossed ___ Pacific on a raft.\"(海洋名前加定冠词)","options":["one","an","a","the"],"answer_index":3,"stem_cn":"海尔达尔乘筏横渡了太平洋。","explanation_cn":"海洋名(the Pacific)前加定冠词。✓ Heyerdahl crossed the Pacific on a raft 海尔达尔乘筏横渡太平洋。✗ a/an 不用于海洋名;✗ one 不合。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp3','choice','{"stem":"\"He has climbed in ___ Alps and the Himalayas.\"(山脉名前加定冠词)","options":["an","a","the","one"],"answer_index":2,"stem_cn":"他曾在阿尔卑斯山和喜马拉雅山攀登。","explanation_cn":"山脉名(the Alps / the Himalayas)前加定冠词。✓ He has climbed in the Alps 他在阿尔卑斯山攀登过。✗ a/an 不用于山脉名;✗ one 不合。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp3','choice','{"stem":"\"She has visited ___ United States twice.\"(国名全称含普通名词时加定冠词)","options":["an","the","a","one"],"answer_index":1,"stem_cn":"她去过美国两次。","explanation_cn":"国名全称里含普通名词(States)时前加定冠词。✓ the United States 美国。✗ a/an 不用于国名;✗ one 不合。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp4','choice','{"stem":"\"One of the children kicked ___ ball very hard.\"(初次提及、单数,辅音前)","options":["some","the","an","a"],"answer_index":3,"stem_cn":"一个孩子狠狠踢了一个球。","explanation_cn":"初次提及、单数、辅音音开头(ball)前用 a。✓ kicked a ball very hard 狠狠踢了一个球。✗ an 用于元音音前;✗ the 表特指;✗ some 接复数/不可数。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp4','choice','{"stem":"\"He saw ___ apple float on the water.\"(下一个词以元音音开头)","options":["some","an","a","the"],"answer_index":1,"stem_cn":"他看见一个苹果浮在水面上。","explanation_cn":"下一个词以元音音开头(apple)时用 an。✓ an apple 一个苹果。✗ a 用于辅音音前;✗ the 表特指;✗ some 接复数/不可数。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp5','choice','{"stem":"\"I sat on ___ riverbank as usual.\"(特指我常坐的那处河岸)","options":["an","a","some","the"],"answer_index":3,"stem_cn":"我像往常一样坐在河岸上。","explanation_cn":"特指\"我常坐的那处河岸\",用定冠词。✓ I sat on the riverbank 我坐在(那处)河岸上。✗ a/an 表泛指初次;✗ some 接复数/不可数。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp5','choice','{"stem":"\"The ball struck the man, and ___ man nearly fell in.\"(再次提及,特指刚说的那人)","options":["one","the","a","an"],"answer_index":1,"stem_cn":"球打中了那人,那人差点掉进水里。","explanation_cn":"上文已提过 the man,再次提及仍用 the。✓ the man nearly fell in 那人差点落水。✗ a/an 用于初次泛指;✗ one 意思是\"一个\"。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp6','choice','{"stem":"\"The ball struck him ___ hard that he nearly fell in.\"(如此…以至于,后接形容词/副词)","options":["very","such","too","so"],"answer_index":3,"stem_cn":"球打得他那么重,他差点落水。","explanation_cn":"\"如此…以至于\",形容词/副词前用 so。✓ so hard that he nearly fell in 那么重,他差点落水。✗ very 后不接 that 从句;✗ too 意思是\"太…(而不能)\";✗ such 后接名词短语。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp6','choice','{"stem":"\"The river was ___ wide that we could not swim across.\"(那么…以至于,填结果连词)","options":["very","so","too","such"],"answer_index":1,"stem_cn":"河那么宽,我们游不过去。","explanation_cn":"\"如此宽…以至于\",形容词 wide 前用 so。✓ so wide that we could not swim across 那么宽,游不过去。✗ such 后接名词;✗ very/too 不与 that 结果从句搭配。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp7','choice','{"stem":"\"The ball went ___ a passing boat.\"(表示\"朝、向\"的方向)","options":["toward","at","for","of"],"answer_index":0,"stem_cn":"球朝一只驶过的小船飞去。","explanation_cn":"表示\"朝、向\"的方向,用 toward。✓ The ball went toward a passing boat 球朝一只驶过的小船飞去。✗ at 指瞄准某点;✗ of 表所属;✗ for 表目的/为了。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp7','choice','{"stem":"\"The children ran ___ the gate and disappeared.\"(朝…方向跑去)","options":["with","from","of","toward"],"answer_index":3,"stem_cn":"孩子们朝大门跑去,不见了。","explanation_cn":"\"朝大门方向跑去\",方向用 toward。✓ ran toward the gate 朝大门跑去。✗ of 表所属;✗ with 表伴随;✗ from 表来源。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp8','choice','{"stem":"\"The Wayle is a river ___ cuts across the park.\"(指物,引导定语从句作主语)","options":["who","whose","that","whom"],"answer_index":2,"stem_cn":"威尔河是一条横穿公园的河。","explanation_cn":"指物(a river),引导定语从句作主语,用 that。✓ a river that cuts across the park 一条横穿公园的河。✗ who/whom 指人;✗ whose 表所属。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',5,'am2_l30_gp8','choice','{"stem":"\"He threw back the ball ___ had hit him.\"(指物,引导定语从句)","options":["whom","where","who","that"],"answer_index":3,"stem_cn":"他把打中他的那个球扔了回去。","explanation_cn":"指物(the ball),引导定语从句,用 that。✓ the ball that had hit him 打中他的那个球。✗ who/whom 指人;✗ where 指地点。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',6,NULL,'choice','{"stem":"美语里踢球的那种球赛(英式叫 football)叫:","options":["polo","kickball","football","soccer"],"answer_index":3,"explanation_cn":"美语里踢球的那种足球叫 soccer;英式叫 football(美语 football 指橄榄球)。✓ play soccer 踢足球。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',6,NULL,'choice','{"stem":"美语里\"朝、向\"常写作(不带 s)的形式是:","options":["toward","onward","forward","towards"],"answer_index":0,"explanation_cn":"美语里\"朝、向\"常写作 toward(不带 s);英式写 towards。✓ walk toward the door 朝门走去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',6,NULL,'choice','{"stem":"polo 的意思是:","options":["网球","篮球","水球;马球","排球"],"answer_index":2,"explanation_cn":"polo = 水球、马球。✓ Football or polo? 足球还是水球?\n顺带记:足球 = soccer;篮球 = basketball;网球 = tennis."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',6,NULL,'choice','{"stem":"动词 cut(cuts across)在本课的意思是:","options":["砍倒","剪短","切碎","穿过"],"answer_index":3,"explanation_cn":"cut(cuts across)在本课意为\"穿过\"。✓ a river that cuts across the park 横穿公园的河。\n顺带记:划(船)= row;踢 = kick;撞、击中 = strike."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',6,NULL,'choice','{"stem":"kick 的意思是:","options":["扔","踢","推","抓"],"answer_index":1,"explanation_cn":"kick = 踢。✓ kicked a ball very hard 狠狠踢了一个球。\n顺带记:扔 = throw;抓 = catch;推 = push."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',6,NULL,'choice','{"stem":"sight(in sight)的意思是:","options":["视野;看得见的范围","气味","声音","味道"],"answer_index":0,"explanation_cn":"sight(in sight)= 视野、看得见的范围;反义 out of sight。✓ there weren''t any in sight 一个也看不见。\n顺带记:几乎 = nearly;河岸 = bank;跑开 = run away."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',7,NULL,'cloze','{"stem":"第 1 空","context":"The Wayle is ___1___ small river that cuts across ___2___ park near my home. Last Sunday some children kicked ___3___ ball so hard ___4___ it nearly hit a man in a boat.","blank_no":1,"options":["a","an","the","some"],"answer_index":0,"explanation_cn":"初次提及、单数、辅音音前(small river)用 a。✓ a small river 一条小河。\n✗ an:用于元音音前;✗ the:表特指;✗ some:接复数/不可数。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',7,NULL,'cloze','{"stem":"第 2 空","context":"The Wayle is ___1___ small river that cuts across ___2___ park near my home. Last Sunday some children kicked ___3___ ball so hard ___4___ it nearly hit a man in a boat.","blank_no":2,"options":["the","a","an","some"],"answer_index":0,"explanation_cn":"特指\"我家附近的那个公园\",用 the。✓ the park near my home 我家附近的公园。\n✗ a/an:表初次泛指;✗ some:接复数/不可数。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',7,NULL,'cloze','{"stem":"第 3 空","context":"The Wayle is ___1___ small river that cuts across ___2___ park near my home. Last Sunday some children kicked ___3___ ball so hard ___4___ it nearly hit a man in a boat.","blank_no":3,"options":["a","an","the","any"],"answer_index":0,"explanation_cn":"初次提及、单数(ball)用 a。✓ kicked a ball 踢了一个球。\n✗ an:用于元音音前;✗ the:表特指;✗ any:多用于否定疑问。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',7,NULL,'cloze','{"stem":"第 4 空","context":"The Wayle is ___1___ small river that cuts across ___2___ park near my home. Last Sunday some children kicked ___3___ ball so hard ___4___ it nearly hit a man in a boat.","blank_no":4,"options":["that","so","which","as"],"answer_index":0,"explanation_cn":"\"如此…以至于\",so 后面配 that 引出结果。✓ so hard that it nearly hit a man 那么重,差点打中一个人。\n✗ so:so 已在前面;✗ which:不引导结果状语;✗ as:不与 so…搭配表结果。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',8,NULL,'choice','{"stem":"Where did the writer sit last Sunday?","options":["In a cafe in the park","On the riverbank by the Wayle","In a small boat on the river","At the top of a mountain"],"answer_index":1,"explanation_cn":"课文说 I went and sat on the riverbank as usual,作者坐在威尔河边的河岸上。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',8,NULL,'choice','{"stem":"What did one of the children do?","options":["Fell into the river","Rowed a boat across the water","Kicked a ball hard toward a passing boat","Threw a stone at a bird"],"answer_index":2,"explanation_cn":"课文说 one of the children kicked a ball very hard, and it went toward a passing boat。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',8,NULL,'choice','{"stem":"What happened to the man in the boat?","options":["The ball struck him and he nearly fell into the water","He caught the ball and smiled","He did not notice anything at all","He rowed away at once"],"answer_index":0,"explanation_cn":"课文说 The ball struck him so hard that he nearly fell into the water,球打中船上的人,他差点落水。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',9,NULL,'choice','{"stem":"你想说\"伦敦在泰晤士河畔\"(河流专名前加定冠词):","options":["London is on a Thames.","London is on Thames.","London is on the Thames.","London is on an Thames."],"answer_index":2,"explanation_cn":"河流专名前加定冠词。✓ London is on the Thames. 场合:说某城在某条河边。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',9,NULL,'choice','{"stem":"你想说\"球朝小船飞去\"(方向用 toward):","options":["The ball went at the boat.","The ball went toward the boat.","The ball went with the boat.","The ball went of the boat."],"answer_index":1,"explanation_cn":"\"朝…去\"方向用 toward。✓ The ball went toward the boat. 场合:描述物体朝某方向移动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',9,NULL,'choice','{"stem":"你想说\"球撞得他那么重,他差点掉进水里\"(如此…以至于):","options":["The ball struck him so hard that he nearly fell in.","The ball struck him such hard that he nearly fell in.","The ball struck him very hard that he nearly fell in.","The ball struck him so hard as he nearly fell in."],"answer_index":0,"explanation_cn":"\"如此…以至于\"用 so + 形容词 + that。✓ struck him so hard that he nearly fell in. 场合:描述程度重到产生某结果。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"polo 的意思是:","options":["足球","篮球","棒球","水球;马球"],"answer_index":3,"explanation_cn":"polo = 水球、马球。✓ Football or polo? 足球还是水球?\n顺带记:足球 = soccer;棒球 = baseball;篮球 = basketball."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"nearly 的意思是:","options":["仔细地","突然","几乎,差不多","从不"],"answer_index":2,"explanation_cn":"nearly = 几乎、差不多。✓ he nearly fell into the water 他差点掉进水里。\n顺带记:突然 = suddenly;仔细地 = carefully;从不 = never."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"\"Heyerdahl crossed ___ Pacific on a raft.\"(海洋专名前加定冠词)","options":["a","an","one","the"],"answer_index":3,"stem_cn":"海尔达尔乘筏横渡太平洋。","explanation_cn":"海洋专名(the Pacific)前加定冠词。✓ crossed the Pacific 横渡太平洋。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"\"There weren''t ___ children in sight.\"(否定句,表示\"任何\")","options":["any","one","much","some"],"answer_index":0,"stem_cn":"一个孩子也看不见。","explanation_cn":"否定句里表示\"任何\"用 any。✓ There weren''t any children in sight 一个孩子也看不见。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"\"The ball went toward the boat.\" 这句话的意思是:","options":["球飞过了小船。","球正好落在船上。","球朝小船飞去。","球从船里飞出。"],"answer_index":2,"explanation_cn":"The ball went toward the boat. toward 表\"朝、向\",意思是\"球朝小船飞去\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"\"They had all run away.\" 这句话的意思是:","options":["他们都留了下来。","他们全都跑掉了。","他们都笑了起来。","他们都睡着了。"],"answer_index":1,"explanation_cn":"They had all run away. run away = 跑开、逃走,意思是\"他们全都跑掉了\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"What is the Wayle?","options":["A famous mountain","A large lake near the sea","A small river that cuts across the park","A busy city street"],"answer_index":2,"passage":"The Wayle is a small river that cuts across the park near my home. I like sitting by the Wayle on fine afternoons. It was warm last Sunday, so I went and sat on the riverbank as usual. Some children were playing games on the bank, and there were some people rowing on the river. Suddenly, one of the children kicked a ball very hard, and it went toward a passing boat. Some people on the bank called out to the man in the boat, but he did not hear them. The ball struck him so hard that he nearly fell into the water. I turned to look at the children, but there weren''t any in sight — they had all run away! The man laughed when he realized what had happened. He called out to the children and threw the ball back to the bank.","explanation_cn":"课文首句 The Wayle is a small river that cuts across the park,威尔河是横穿公园的一条小河。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"Why couldn''t the writer see any children afterward?","options":["They had gone home for lunch","They had all run away","They were hiding in the boat","They were swimming in the river"],"answer_index":1,"passage":"The Wayle is a small river that cuts across the park near my home. I like sitting by the Wayle on fine afternoons. It was warm last Sunday, so I went and sat on the riverbank as usual. Some children were playing games on the bank, and there were some people rowing on the river. Suddenly, one of the children kicked a ball very hard, and it went toward a passing boat. Some people on the bank called out to the man in the boat, but he did not hear them. The ball struck him so hard that he nearly fell into the water. I turned to look at the children, but there weren''t any in sight — they had all run away! The man laughed when he realized what had happened. He called out to the children and threw the ball back to the bank.","explanation_cn":"课文说 there weren''t any in sight: they had all run away,孩子们全跑光了,所以看不见。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"What happened to the man in the boat?","options":["He won a game of polo","He caught all the children","The ball struck him and he nearly fell into the water","He rowed safely to the bank"],"answer_index":2,"audio":"The Wayle is a small river that cuts across the park near my home. I like sitting by the Wayle on fine afternoons. It was warm last Sunday, so I went and sat on the riverbank as usual. Some children were playing games on the bank, and there were some people rowing on the river. Suddenly, one of the children kicked a ball very hard, and it went toward a passing boat. Some people on the bank called out to the man in the boat, but he did not hear them. The ball struck him so hard that he nearly fell into the water. I turned to look at the children, but there weren''t any in sight — they had all run away! The man laughed when he realized what had happened. He called out to the children and threw the ball back to the bank.","explanation_cn":"课文说球 struck him so hard that he nearly fell into the water,球打中船上人,他差点落水。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l30',10,NULL,'choice','{"stem":"How did the man react when he realized what had happened?","options":["He got angry and shouted","He laughed and threw the ball back","He called the police","He rowed away quickly"],"answer_index":1,"audio":"The Wayle is a small river that cuts across the park near my home. I like sitting by the Wayle on fine afternoons. It was warm last Sunday, so I went and sat on the riverbank as usual. Some children were playing games on the bank, and there were some people rowing on the river. Suddenly, one of the children kicked a ball very hard, and it went toward a passing boat. Some people on the bank called out to the man in the boat, but he did not hear them. The ball struck him so hard that he nearly fell into the water. I turned to look at the children, but there weren''t any in sight — they had all run away! The man laughed when he realized what had happened. He called out to the children and threw the ball back to the bank.","explanation_cn":"课文结尾 The man laughed when he realized what had happened… threw the ball back,那人笑着把球扔了回去。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l31',2,4,31,'Success story','成功者的故事','used to do 表过去的习惯/状态(现已停止、不再重复:used to work / used to be)· 与一般过去时(一次性动作)、过去进行时(当时正在做)对比(主考)+ which 引导定语从句(指物)/ when 引导时间状语从句(辅考·课文①类)','昨天下午弗兰克·霍金斯向''我''讲他年轻时的经历。退休前他是一家大公司的负责人,但小时候他曾在一家小店做工,专修自行车,一天要干14个小时。他积蓄多年,1958年买下自己的一间小车间;二十几岁时给飞机做零配件,雇了两个帮手。几年后小车间变成了一家雇有728人的大工厂。他回想早年的艰辛,微笑着——正笑着,门开了,妻子进来要他去修孙子的自行车!','{"q":"Listen and answer — What was Frank''s first job?","options":["He used to repair bicycles in a small store","He made airplanes in a factory","He was a taxi driver","He was a mailman"],"answer_index":0}'::jsonb,'{"title":"used to do:过去的习惯与状态","intro":"used to + 动词原形,表示过去经常做、或过去的状态,而现在已经停止、不再这样。跟''一次性动作(一般过去时)''和''当时正在做(过去进行时)''不同。全用本课和 Key structures 的句子举例。","table":{"headers":["表达","例子"],"rows":[["过去经常做(现已停止)","He used to work fourteen hours a day."],["过去的状态(现已改变)","He used to be a mailman. He''s a taxi driver now."],["否定 / 疑问","He didn''t use to smoke. Did you use to collect stamps?"],["对比:一次性动作 → 一般过去","In 1958 he bought a workshop."],["对比:当时正在做 → 过去进行","When I was watering the garden, it began to rain."]]},"specialRules":[{"rule":"which 引导定语从句指物:a factory which employed 728 people 一家雇了728人的工厂","mark":"which 定从"},{"rule":"when 引导时间状语从句''当…时'':He was still smiling when the door opened.","mark":"when 状从"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',1,NULL,'Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man.','昨天下午,弗兰克·霍金斯向我讲述了他年轻时的经历。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',2,NULL,'Before he retired, Frank was the head of a very large business company, but as a boy he used to work in a small store.','退休前,弗兰克是一家非常大的商业公司的负责人,但小时候他曾在一家小店做工。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',3,NULL,'It was his job to repair bicycles, and at that time he used to work fourteen hours a day.','他那时的工作是修理自行车,而且经常一天工作14个小时。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',4,NULL,'He saved money for years, and in 1958 he bought a small workshop of his own.','他积蓄多年,于1958年买下了自己的一间小车间。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',5,NULL,'In his twenties, Frank used to make spare parts for airplanes.','二十几岁时,弗兰克常给飞机制造零配件。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',6,NULL,'At that time he had two helpers.','那时他有两个帮手。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',7,NULL,'In a few years the small workshop had become a large factory which employed seven hundred and twenty-eight people.','几年之后,那间小车间已发展成一家雇有728人的大工厂。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',8,NULL,'Frank smiled when he remembered his hard early years and the long road to success.','弗兰克回想起早年的艰辛和漫长的成功之路,笑了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',9,NULL,'He was still smiling when the door opened and his wife came in.','他正笑着,门开了,他的妻子走了进来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l31',10,NULL,'She wanted him to repair their grandson''s bicycle!','她要他去修孙子的自行车!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
