INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l31_gp8','am2_l31','when 引导时间状语从句(辅考)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l31','airplane','aeroplane','飞机;美语 airplane,英式 aeroplane(课文 spare parts for airplanes)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l31','mailman','postman','邮递员;美语 mailman / mail carrier,英式 postman') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l31','store','shop','商店;美语零售店常说 store,英式 shop(修理工场仍叫 workshop)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l31','elevator','lift','电梯;美语 elevator,英式 lift(高频美语点)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l31','used to do','',NULL,'/juːst tuː duː/','He used to work fourteen hours a day.','他过去一天工作14个小时。','I used to go to work by bus.','我过去常坐公交上班。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l31','spare parts','',NULL,'/sper pɑːrts/','He used to make spare parts for airplanes.','他过去给飞机做零配件。','We need spare parts for the car.','我们需要汽车的零配件。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l31','the head of','',NULL,'/ðə hed əv/','Frank was the head of a large company.','弗兰克曾是一家大公司的负责人。','She is the head of the school.','她是学校的负责人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l31','in his twenties','',NULL,'/ɪn hɪz ˈtwentiz/','In his twenties, Frank made spare parts.','二十几岁时,弗兰克做零配件。','She got married in her twenties.','她二十几岁时结了婚。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp1','choice','{"stem":"\"As a boy, Frank ___ work in a small store.\"(过去经常做、现已停止)","options":["is used to","use to","was used to","used to"],"answer_index":3,"stem_cn":"弗兰克小时候常在一家小店做工。","explanation_cn":"表示过去经常做、现在已不再,用 used to + 动词原形。✓ he used to work in a small store 他过去在小店做工。✗ use to:肯定句要用 used to;✗ is used to / was used to:意为\"习惯于\",后接名词或 doing,意思不同。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp1','choice','{"stem":"\"He ___ work fourteen hours a day.\"(过去经常做、现已停止)","options":["use to","used to","is used to","uses to"],"answer_index":1,"stem_cn":"他过去一天工作14个小时。","explanation_cn":"过去经常做、现已停止,用 used to。✓ used to work fourteen hours a day 过去一天工作14小时。✗ use to:肯定句用 used to;✗ uses to / is used to:形式或意义都不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp1','choice','{"stem":"\"I ___ go to work by bus. Now I go by car.\"(过去经常,现在变了)","options":["was used to","am used to","use to","used to"],"answer_index":3,"stem_cn":"我过去常坐公交上班,现在开车去。","explanation_cn":"过去经常、现在变了,用 used to。✓ I used to go to work by bus. Now I go by car. ✗ use to:肯定句用 used to;✗ am used to / was used to:意为\"习惯于\",不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp2','choice','{"stem":"\"He ___ be a mailman a long time ago.\"(过去的状态,现已改变)","options":["uses to","used to","is used to","use to"],"answer_index":1,"stem_cn":"很久以前他曾是个邮递员。","explanation_cn":"过去的状态、现已改变,用 used to be。✓ He used to be a mailman 他过去是个邮递员。✗ use to:肯定句用 used to;✗ is used to / uses to:形式或意义不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp2','choice','{"stem":"\"My uncle ___ live in New Zealand, but he lives in Australia now.\"(过去的状态,现已改变)","options":["was used to","use to","used to","is used to"],"answer_index":2,"stem_cn":"我叔叔过去住新西兰,现在住澳大利亚。","explanation_cn":"过去住某地、现已搬走,用 used to live。✓ My uncle used to live in New Zealand 我叔叔过去住新西兰。✗ use to;✗ is used to / was used to:意为\"习惯于\",不合。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp3','choice','{"stem":"\"Frank ___ use to work in an office.\"(过去习惯的否定)","options":["wasn''t","isn''t","doesn''t","didn''t"],"answer_index":3,"stem_cn":"弗兰克过去不在办公室工作。","explanation_cn":"过去习惯的否定用 didn''t use to。✓ Frank didn''t use to work in an office 弗兰克过去不在办公室工作。✗ doesn''t:这是过去的事;✗ isn''t / wasn''t:use to 要用助动词 did 否定。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp3','choice','{"stem":"\"___ you use to collect stamps as a boy?\"(过去习惯的一般疑问)","options":["Do","Are","Did","Were"],"answer_index":2,"stem_cn":"你小时候常集邮吗?","explanation_cn":"过去习惯的一般疑问用 Did…use to。✓ Did you use to collect stamps? 你过去常集邮吗?✗ Do:问的是过去;✗ Are / Were:use to 要用 did 提问。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp4','choice','{"stem":"\"In 1958 he ___ a small workshop of his own.\"(1958 一次性动作,用一般过去)","options":["buys","was buying","used to buy","bought"],"answer_index":3,"stem_cn":"1958年他买下了自己的一间小车间。","explanation_cn":"有明确一次性时间(in 1958),用一般过去时。✓ In 1958 he bought a small workshop 1958年他买下了小车间。✗ used to buy:那是一次性动作不是习惯;✗ buys / was buying:时态不对。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp4','choice','{"stem":"\"Yesterday afternoon Frank ___ me about his experiences.\"(yesterday 一次性,用一般过去)","options":["is telling","told","used to tell","tells"],"answer_index":1,"stem_cn":"昨天下午弗兰克跟我讲了他的经历。","explanation_cn":"yesterday afternoon 一次性动作,用一般过去时。✓ Frank told me about his experiences 弗兰克跟我讲了他的经历。✗ used to tell:不是反复习惯;✗ tells / is telling:时态不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp4','choice','{"stem":"\"In a few years the workshop ___ a large factory.\"(一次性结果,用一般过去)","options":["became","used to become","becomes","was becoming"],"answer_index":0,"stem_cn":"几年后那间车间变成了一家大工厂。","explanation_cn":"\"几年后变成\"是一次性结果,用一般过去时。✓ the workshop became a large factory 车间变成了大工厂。✗ used to become:不是反复习惯;✗ becomes / was becoming:时态不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp5','choice','{"stem":"\"When I ___ the garden, it began to rain.\"(当时正在进行,用过去进行)","options":["watered","water","was watering","used to water"],"answer_index":2,"stem_cn":"我正在浇花园时,天开始下雨。","explanation_cn":"\"当时正在浇花园\"用过去进行时。✓ When I was watering the garden, it began to rain 我正浇花园时天下起雨。✗ used to water:不是习惯;✗ watered / water:表达不出\"正在\"。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp5','choice','{"stem":"\"As I ___ on the bus, I slipped and hurt my foot.\"(正上车那一刻,用过去进行)","options":["got","used to get","get","was getting"],"answer_index":3,"stem_cn":"我正上公交车时,滑了一下伤了脚。","explanation_cn":"\"正上公交车那一刻\"用过去进行时。✓ As I was getting on the bus, I slipped 我正上车时滑了一下。✗ used to get:不是习惯;✗ got / get:表达不出\"正在\"。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp6','choice','{"stem":"\"Frank ___ to work in a shop, but now he is retired.\"(过去经常,与现在对比)","options":["use","used","uses","is used"],"answer_index":1,"stem_cn":"弗兰克过去在店里做工,现在退休了。","explanation_cn":"过去经常做、与现在对比,used to + 原形。✓ Frank used to work in a shop, but now he is retired. ✗ use:肯定句用 used;✗ uses / is used:形式或意义不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp6','choice','{"stem":"\"I ___ to collect stamps, but I don''t anymore.\"(过去经常,现在不做了)","options":["used","am used","was used","use"],"answer_index":0,"stem_cn":"我过去集邮,现在不集了。","explanation_cn":"过去经常、现在不做了,used to。✓ I used to collect stamps, but I don''t anymore. ✗ use:肯定句用 used;✗ am used / was used:意为\"习惯于\",不合。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp7','choice','{"stem":"\"It became a large factory ___ employed 728 people.\"(指物,引导定语从句)","options":["whom","who","which","whose"],"answer_index":2,"stem_cn":"它变成了一家雇了728人的大工厂。","explanation_cn":"指物(a factory),引导定语从句,用 which。✓ a factory which employed 728 people 一家雇了728人的工厂。✗ who / whom:指人;✗ whose:表所属。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp7','choice','{"stem":"\"He repaired the bicycle ___ his grandson rode.\"(指物,引导定语从句)","options":["which","where","who","whom"],"answer_index":0,"stem_cn":"他修好了孙子骑的那辆自行车。","explanation_cn":"指物(the bicycle),引导定语从句,用 which。✓ the bicycle which his grandson rode 他孙子骑的那辆自行车。✗ who / whom:指人;✗ where:指地点。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp8','choice','{"stem":"\"Frank smiled ___ he remembered his early years.\"(表示''当…的时候'')","options":["which","that","when","what"],"answer_index":2,"stem_cn":"弗兰克回想起早年时笑了。","explanation_cn":"表示\"当…的时候\",引导时间状语从句用 when。✓ Frank smiled when he remembered his early years 他回想早年时笑了。✗ which / that:不引导时间状语;✗ what:不引导时间状语。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',5,'am2_l31_gp8','choice','{"stem":"\"He was still smiling ___ the door opened.\"(表示''当…的时候'')","options":["who","what","which","when"],"answer_index":3,"stem_cn":"门开的时候他还在微笑。","explanation_cn":"表示\"当…的时候\",用 when。✓ He was still smiling when the door opened 门开时他还在微笑。✗ which / who:引导定语从句;✗ what:不合。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',6,NULL,'choice','{"stem":"美语里\"飞机\"常说:","options":["air machine","airplane","aeroplane","sky car"],"answer_index":1,"explanation_cn":"美语里\"飞机\"常说 airplane;英式说 aeroplane。✓ spare parts for airplanes 飞机的零配件。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',6,NULL,'choice','{"stem":"美语里\"邮递员\"常说:","options":["mailman","letter man","postman","post boy"],"answer_index":0,"explanation_cn":"美语里\"邮递员\"常说 mailman / mail carrier;英式说 postman。✓ He used to be a mailman 他过去是邮递员。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',6,NULL,'choice','{"stem":"retire 的意思是:","options":["积蓄","退休","雇用","修理"],"answer_index":1,"explanation_cn":"retire = 退休。✓ Before he retired 在他退休前。\n顺带记:雇用 = employ;修理 = repair;积蓄 = save."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',6,NULL,'choice','{"stem":"employ 的意思是:","options":["退休","出售","雇用","解雇"],"answer_index":2,"explanation_cn":"employ = 雇用。✓ a factory which employed 728 people 雇了728人的工厂。\n顺带记:退休 = retire;解雇 = fire;出售 = sell."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',6,NULL,'choice','{"stem":"save(save money)的意思是:","options":["丢失","积蓄,储蓄","借出","花费"],"answer_index":1,"explanation_cn":"save(save money)= 积蓄、储蓄。✓ He saved money for years 他积蓄了多年。\n顺带记:花费 = spend;借出 = lend;丢失 = lose."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',6,NULL,'choice','{"stem":"helper 的意思是:","options":["顾客","老板","对手","帮手,助手"],"answer_index":3,"explanation_cn":"helper = 帮手、助手。✓ he had two helpers 他有两个帮手。\n顺带记:老板 = boss;顾客 = customer;工厂 = factory."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',7,NULL,'cloze','{"stem":"第 1 空","context":"As a boy, Frank ___1___ to work in a small store. In 1958 he ___2___ a workshop of his own. It became a large factory ___3___ employed many people. He smiled ___4___ he remembered those years.","blank_no":1,"options":["used","use","uses","is used"],"answer_index":0,"explanation_cn":"过去经常做、现已停止,用 used to。✓ Frank used to work in a small store 弗兰克过去在小店做工。\n✗ use:肯定句用 used;✗ uses:时态不对;✗ is used:意为\"习惯于\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',7,NULL,'cloze','{"stem":"第 2 空","context":"As a boy, Frank ___1___ to work in a small store. In 1958 he ___2___ a workshop of his own. It became a large factory ___3___ employed many people. He smiled ___4___ he remembered those years.","blank_no":2,"options":["bought","used to buy","buys","was buying"],"answer_index":0,"explanation_cn":"有明确时间(in 1958),一次性动作用一般过去。✓ he bought a workshop 他买下了车间。\n✗ used to buy:不是反复习惯;✗ buys:时态不对;✗ was buying:表达不出\"买成了\"。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',7,NULL,'cloze','{"stem":"第 3 空","context":"As a boy, Frank ___1___ to work in a small store. In 1958 he ___2___ a workshop of his own. It became a large factory ___3___ employed many people. He smiled ___4___ he remembered those years.","blank_no":3,"options":["which","who","whom","whose"],"answer_index":0,"explanation_cn":"指物(a large factory),引导定语从句。✓ a factory which employed many people。\n✗ who / whom:指人;✗ whose:表所属。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',7,NULL,'cloze','{"stem":"第 4 空","context":"As a boy, Frank ___1___ to work in a small store. In 1958 he ___2___ a workshop of his own. It became a large factory ___3___ employed many people. He smiled ___4___ he remembered those years.","blank_no":4,"options":["when","which","what","that"],"answer_index":0,"explanation_cn":"表示\"当…的时候\",时间状语从句用 when。✓ He smiled when he remembered those years。\n✗ which:引导定语从句;✗ what:不合;✗ that:不引导时间状语。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',8,NULL,'choice','{"stem":"What was Frank''s first job as a boy?","options":["Delivering mail","Repairing bicycles in a small store","Driving a taxi","Making airplanes in a factory"],"answer_index":1,"explanation_cn":"课文说 as a boy he used to work in a small store… It was his job to repair bicycles,他小时候在小店修自行车。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',8,NULL,'choice','{"stem":"What did Frank use to make in his twenties?","options":["Spare parts for airplanes","Clothes for a company","Bicycles for children","Furniture for shops"],"answer_index":0,"explanation_cn":"课文说 In his twenties, Frank used to make spare parts for airplanes,他二十几岁时给飞机做零配件。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',8,NULL,'choice','{"stem":"What did his wife want him to repair?","options":["A neighbor''s car","His old workshop","The factory machines","Their grandson''s bicycle"],"answer_index":3,"explanation_cn":"课文结尾 She wanted him to repair their grandson''s bicycle,妻子要他去修孙子的自行车。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',9,NULL,'choice','{"stem":"你想说\"我过去常坐公交上班\"(过去经常用 used to):","options":["I use to go to work by bus.","I used to go to work by bus.","I was used to go to work by bus.","I am used to go to work by bus."],"answer_index":1,"explanation_cn":"\"过去经常\"用 used to + 原形。✓ I used to go to work by bus. 场合:说自己过去的习惯,现在已变。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',9,NULL,'choice','{"stem":"你想说\"那是一家雇了728人的工厂\"(指物用 which 引导):","options":["a factory who employed 728 people","a factory what employed 728 people","a factory where employed 728 people","a factory which employed 728 people"],"answer_index":3,"explanation_cn":"指物时用 which 来引导后面的修饰句。✓ a factory which employed 728 people. 场合:接在\"工厂\"后面说明它雇了多少人。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',9,NULL,'choice','{"stem":"你想说\"门开时他还在微笑\"(表''当…时''用 when):","options":["He was still smiling what the door opened.","He was still smiling where the door opened.","He was still smiling when the door opened.","He was still smiling which the door opened."],"answer_index":2,"explanation_cn":"\"当…的时候\"用 when 引导。✓ He was still smiling when the door opened. 场合:说一件事发生时另一件事正在进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"retire 的意思是:","options":["积蓄","雇用","上班","退休"],"answer_index":3,"explanation_cn":"retire = 退休。✓ Before he retired 在他退休前。\n顺带记:上班 = go to work;雇用 = employ;积蓄 = save."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"employ 的意思是:","options":["退休","修理","雇用","解雇"],"answer_index":2,"explanation_cn":"employ = 雇用。✓ a factory which employed 728 people。\n顺带记:解雇 = fire;退休 = retire;修理 = repair."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"\"As a boy, Frank ___ work in a small store.\"(过去经常做、现已停止)","options":["is used to","was used to","use to","used to"],"answer_index":3,"stem_cn":"弗兰克小时候常在一家小店做工。","explanation_cn":"过去经常做、现已停止,用 used to。✓ Frank used to work in a small store 弗兰克过去在小店做工。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"\"It became a factory ___ employed 728 people.\"(指物,引导定语从句)","options":["which","who","whom","whose"],"answer_index":0,"stem_cn":"它变成了一家雇了728人的工厂。","explanation_cn":"指物,引导定语从句用 which。✓ a factory which employed 728 people 雇了728人的工厂。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"\"He used to work fourteen hours a day.\" 这句话的意思是:","options":["他明天要工作14个小时。","他现在一天工作14个小时。","他从不工作14个小时。","他过去一天工作14个小时。"],"answer_index":3,"explanation_cn":"He used to work fourteen hours a day. used to 表过去的习惯,意思是\"他过去一天工作14个小时\"(现在不这样了)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"\"She wanted him to repair their grandson''s bicycle.\" 这句话的意思是:","options":["她要他骑自行车。","她要他买一辆自行车。","她要他修孙子的自行车。","她要他卖掉自行车。"],"answer_index":2,"explanation_cn":"She wanted him to repair their grandson''s bicycle. want sb to do = 要某人做某事,意思是\"她要他修孙子的自行车\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"What was Frank before he retired?","options":["The head of a very large business company","A mailman","A bicycle repairman","A factory worker"],"answer_index":0,"passage":"Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man. Before he retired, Frank was the head of a very large business company, but as a boy he used to work in a small store. It was his job to repair bicycles, and at that time he used to work fourteen hours a day. He saved money for years, and in 1958 he bought a small workshop of his own. In his twenties, Frank used to make spare parts for airplanes. At that time he had two helpers. In a few years the small workshop had become a large factory which employed seven hundred and twenty-eight people. Frank smiled when he remembered his hard early years and the long road to success. He was still smiling when the door opened and his wife came in. She wanted him to repair their grandson''s bicycle!","explanation_cn":"课文说 Before he retired, Frank was the head of a very large business company,退休前他是大公司的负责人。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"How did the small workshop change over a few years?","options":["It closed down completely","It became a large factory employing 728 people","It stayed a small shop","It became a bicycle store"],"answer_index":1,"passage":"Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man. Before he retired, Frank was the head of a very large business company, but as a boy he used to work in a small store. It was his job to repair bicycles, and at that time he used to work fourteen hours a day. He saved money for years, and in 1958 he bought a small workshop of his own. In his twenties, Frank used to make spare parts for airplanes. At that time he had two helpers. In a few years the small workshop had become a large factory which employed seven hundred and twenty-eight people. Frank smiled when he remembered his hard early years and the long road to success. He was still smiling when the door opened and his wife came in. She wanted him to repair their grandson''s bicycle!","explanation_cn":"课文说 the small workshop had become a large factory which employed 728 people,小车间变成了大工厂。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"What was Frank''s first job?","options":["Making airplanes","Driving a bus","Running a factory","Repairing bicycles in a small store"],"answer_index":3,"audio":"Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man. Before he retired, Frank was the head of a very large business company, but as a boy he used to work in a small store. It was his job to repair bicycles, and at that time he used to work fourteen hours a day. He saved money for years, and in 1958 he bought a small workshop of his own. In his twenties, Frank used to make spare parts for airplanes. At that time he had two helpers. In a few years the small workshop had become a large factory which employed seven hundred and twenty-eight people. Frank smiled when he remembered his hard early years and the long road to success. He was still smiling when the door opened and his wife came in. She wanted him to repair their grandson''s bicycle!","explanation_cn":"课文说他小时候 used to work in a small store 修自行车,那是他的第一份工作。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l31',10,NULL,'choice','{"stem":"Who came into the room while Frank was smiling?","options":["His grandson","His wife","His old boss","His helper"],"answer_index":1,"audio":"Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man. Before he retired, Frank was the head of a very large business company, but as a boy he used to work in a small store. It was his job to repair bicycles, and at that time he used to work fourteen hours a day. He saved money for years, and in 1958 he bought a small workshop of his own. In his twenties, Frank used to make spare parts for airplanes. At that time he had two helpers. In a few years the small workshop had become a large factory which employed seven hundred and twenty-eight people. Frank smiled when he remembered his hard early years and the long road to success. He was still smiling when the door opened and his wife came in. She wanted him to repair their grandson''s bicycle!","explanation_cn":"课文说 He was still smiling when the door opened and his wife came in,进来的是他的妻子。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l32',2,4,32,'Shopping made easy','购物变得很方便','as…as / not so…as 同级比较(和…一样 / 不如…那样,KS8)+ 比较级 than / 最高级 the most + 量词 much/many 与 little/few/a little/a few(主考)+ it 形式主语(it is + adj + for sb + to do)/ 介词 + 动名词(without paying)(辅考·课文①类)','人们不再像从前那样诚实,偷窃的诱惑比以往更大——尤其在大商店里。一名侦探最近盯上一位总在星期一上午进大商店的穿着讲究的妇女。一个星期一,店里人比平常少,侦探更容易监视她。妇女先买了几样小商品,过一会儿又挑了一件最贵的连衣裙,递给一个售货员让她尽快包好;然后妇女拿起包裹没付钱就走出商店。她被捕后,侦探发现那售货员竟是她女儿——那姑娘每星期''送''母亲一件免费的连衣裙!','{"q":"Listen and answer — Who was the thief?","options":["The well-dressed woman (helped by her daughter)","The shop assistant alone","The detective","The store manager"],"answer_index":0}'::jsonb,'{"title":"as…as 同级比较 与 量词","intro":"as + 形容词/副词 + as 表示''和…一样'';not so/as … as 表示''不如…那样''。再复习比较级 than、最高级 the most,以及量词 much/many 和 little/few/a little/a few。全用本课和 Key structures 的句子举例。","table":{"headers":["表达","例子"],"rows":[["和…一样 → as … as","He is as old as I am."],["不如…那样 → not so/as … as","People are not so honest as they once were."],["尽可能… → as … as possible","He wrapped it up as quickly as possible."],["更… → 比较级 + than","fewer people than usual"],["最… → the most / -est","one of the most expensive dresses"]]},"specialRules":[{"rule":"it 作形式主语,真正主语是后面的不定式:It was easier for the detective to watch her.","mark":"it…for sb to do"},{"rule":"介词后面动词用 -ing 形式:walked out without paying;量词 little/few 表''几乎没有'',a little/a few 表''一些''","mark":"介词+-ing / 量词"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',1,NULL,'People are not so honest as they once were.','人们不像从前那样诚实了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',2,NULL,'The temptation to steal is greater than ever before — especially in large stores.','偷窃的诱惑比以往任何时候都更强烈——尤其是在大商店里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',3,NULL,'A detective recently watched a well-dressed woman who always went into a large store on Monday mornings.','一名侦探最近注意上了一位总在星期一上午进大商店的穿着讲究的妇女。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',4,NULL,'One Monday, there were fewer people in the store than usual when the woman came in, so it was easier for the detective to watch her.','一个星期一,那妇女进来时店里的人比平常少,因此侦探更容易监视她。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',5,NULL,'The woman first bought a few small articles.','那妇女先买了几样小商品。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',6,NULL,'After a little time, she chose one of the most expensive dresses in the store and handed it to an assistant who wrapped it up for her as quickly as possible.','过了一会儿,她挑了店里最贵的一件连衣裙,递给一个售货员,让她尽快包好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',7,NULL,'Then the woman simply took the package and walked out of the store without paying.','然后那妇女拿起包裹,没付钱就走出了商店。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',8,NULL,'When she was arrested, the detective found out that the assistant was her daughter.','她被捕后,侦探发现那售货员原来是她的女儿。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l32',9,NULL,'The girl ''gave'' her mother a free dress once a week!','那姑娘每星期''送''母亲一件免费的连衣裙!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l32','once','/wʌns/','adv','曾经,以前','as they once were') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
