INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l32','store','shop','商店;美语 store(大商店 department store),英式 shop(课文 large store)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l32','package','parcel','包裹;美语 package,英式 parcel(课文 took the package)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l32','sales clerk','shop assistant','售货员;美语 sales clerk / salesperson,英式 shop assistant') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l32','mall','shopping centre','购物中心;美语 mall,英式 shopping centre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l32','as ... as possible','',NULL,'/æz ... æz ˈpɑːsəbəl/','He wrapped it up as quickly as possible.','他尽快把它包好。','Come as soon as possible.','请尽快来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l32','the temptation to do','',NULL,'/ðə tempˈteɪʃən tuː duː/','The temptation to steal is great.','偷窃的诱惑很大。','I resisted the temptation to buy it.','我忍住了买它的诱惑。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l32','without paying','',NULL,'/wɪˈðaʊt ˈpeɪɪŋ/','She walked out without paying.','她没付钱就走了出去。','He left without saying goodbye.','他没道别就走了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l32','one of the most ...','',NULL,'/wʌn əv ðə moʊst/','one of the most expensive dresses','最贵的连衣裙之一','one of the most famous singers','最有名的歌手之一') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp1','choice','{"stem":"\"He is ___ old as I am.\"(表示''和…一样'')","options":["as","too","so","very"],"answer_index":0,"stem_cn":"他和我年龄一样大。","explanation_cn":"\"和…一样\"用 as + 形容词 + as,前一个 as 在形容词前。✓ He is as old as I am 他和我一样大。✗ so:so…as 只用于否定;✗ very / too:不构成同级比较。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp1','choice','{"stem":"\"She ran ___ fast as her brother.\"(表示''和…一样快'')","options":["so","more","very","as"],"answer_index":3,"stem_cn":"她跑得和她哥哥一样快。","explanation_cn":"\"和…一样快\"用 as fast as。✓ She ran as fast as her brother 她跑得和哥哥一样快。✗ so:肯定句同级用 as;✗ more:那是比较级;✗ very:不构成比较。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp1','choice','{"stem":"\"He unlocked the door as quickly ___ he could.\"(同级比较的第二个词)","options":["as","that","than","so"],"answer_index":0,"stem_cn":"他尽快把门打开了。","explanation_cn":"同级比较的第二个词也是 as。✓ as quickly as he could 尽他所能地快。✗ than:那是比较级用的;✗ so / that:不构成同级比较。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp2','choice','{"stem":"\"People are not ___ honest as they once were.\"(表示''不如…那样'')","options":["more","too","so","very"],"answer_index":2,"stem_cn":"人们不像从前那样诚实了。","explanation_cn":"\"不如…那样\"可用 not so … as。✓ People are not so honest as they once were 人们不像从前那样诚实。✗ very / too:不构成比较;✗ more:意思相反。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp2','choice','{"stem":"\"She is not ___ intelligent as we think.\"(表示''不如…那样'')","options":["very","much","too","so"],"answer_index":3,"stem_cn":"她不像我们想的那么聪明。","explanation_cn":"\"不如…那样\"用 not so … as。✓ She is not so intelligent as we think 她不像我们想的那么聪明。✗ very / too:不构成比较;✗ much:不合。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp2','choice','{"stem":"\"This book is not ___ interesting as that one.\"(表示''不如…那样'')","options":["too","as","very","more"],"answer_index":1,"stem_cn":"这本书不如那本有趣。","explanation_cn":"否定同级也可用 not as … as。✓ This book is not as interesting as that one 这本书不如那本有趣。✗ very / too:不构成比较;✗ more:意思相反。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp3','choice','{"stem":"\"He wrapped it up ___ quickly as possible.\"(表示''尽可能…'')","options":["more","very","so","as"],"answer_index":3,"stem_cn":"他尽快把它包好。","explanation_cn":"\"尽可能…\"用 as … as possible。✓ as quickly as possible 尽可能快。✗ so:肯定用 as;✗ more:那是比较级;✗ very:不构成比较。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp3','choice','{"stem":"\"Please come ___ soon as you can.\"(表示''尽…'')","options":["more","so","as","than"],"answer_index":2,"stem_cn":"请尽快来。","explanation_cn":"\"尽…\"用 as … as you can。✓ as soon as you can 尽你所能地快。✗ so:肯定用 as;✗ than:比较级用;✗ more:不合。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp4','choice','{"stem":"\"The temptation to steal is ___ than ever before.\"(比…更强,用比较级)","options":["greater","greatest","great","more great"],"answer_index":0,"stem_cn":"偷窃的诱惑比以往任何时候都更强烈。","explanation_cn":"\"比…更强\"用比较级 greater。✓ greater than ever before 比以往任何时候都强。✗ great:原级;✗ greatest:最高级;✗ more great:great 是单音节,直接加 -er。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp4','choice','{"stem":"\"There were ___ people than usual that Monday.\"(比…少,修饰可数名词)","options":["few","fewer","less","little"],"answer_index":1,"stem_cn":"那个星期一人比平常少。","explanation_cn":"\"比…少\",修饰可数名词(people)用 fewer。✓ fewer people than usual 比平常少的人。✗ less:修饰不可数;✗ few:缺少比较级形式;✗ little:修饰不可数。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp5','choice','{"stem":"\"She chose one of the ___ expensive dresses.\"(表示''最…'')","options":["much","very","more","most"],"answer_index":3,"stem_cn":"她挑了一件最贵的连衣裙。","explanation_cn":"\"最贵的\"用最高级 the most + expensive。✓ one of the most expensive dresses 最贵的连衣裙之一。✗ more:比较级;✗ much / very:不构成最高级。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp5','choice','{"stem":"\"It was the ___ store in town.\"(表示''最大的'')","options":["most big","bigger","biggest","big"],"answer_index":2,"stem_cn":"那是城里最大的商店。","explanation_cn":"\"最大的\"用最高级 biggest(big 双写 g 加 -est)。✓ the biggest store in town 城里最大的商店。✗ bigger:比较级;✗ most big:big 是单音节不用 most;✗ big:原级。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp6','choice','{"stem":"\"The woman first bought ___ small articles.\"(可数名词,表示''几样'')","options":["much","a few","a little","little"],"answer_index":1,"stem_cn":"那妇女先买了几样小商品。","explanation_cn":"可数名词(articles),\"几样\"用 a few。✓ a few small articles 几样小商品。✗ a little:修饰不可数;✗ much:修饰不可数;✗ little:表\"几乎没有\"。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp6','choice','{"stem":"\"There is ___ milk in the bottle, so we can''t make tea.\"(不可数,表示''几乎没有'')","options":["few","many","little","a few"],"answer_index":2,"stem_cn":"瓶里几乎没有牛奶,泡不了茶。","explanation_cn":"不可数(milk),\"几乎没有\"用 little。✓ There is little milk 几乎没有牛奶。✗ few:修饰可数;✗ a few:修饰可数;✗ many:修饰可数。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp7','choice','{"stem":"\"It was easier ___ the detective to watch her.\"(it 是形式主语,真正主语在后面)","options":["of","to","with","for"],"answer_index":3,"stem_cn":"侦探更容易监视她了。","explanation_cn":"it 作形式主语,真正主语是后面的不定式,动作发出者前用 for。✓ It was easier for the detective to watch her 侦探更容易监视她。✗ of:多用于表人品的形容词(kind of you);✗ to / with:不合。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp7','choice','{"stem":"\"It is important ___ us to be honest.\"(it 是形式主语,真正主语在后面)","options":["to","for","that","of"],"answer_index":1,"stem_cn":"诚实对我们很重要。","explanation_cn":"it 作形式主语,动作发出者前用 for。✓ It is important for us to be honest 诚实对我们很重要。✗ of:此处形容词不表人品;✗ to / that:不合。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp8','choice','{"stem":"\"The woman walked out without ___.\"(介词后面动词用 -ing 形式)","options":["paying","paid","to pay","pay"],"answer_index":0,"stem_cn":"那妇女没付钱就走了出去。","explanation_cn":"介词 without 后面动词用 -ing 形式。✓ walked out without paying 没付钱就走了。✗ pay / paid:介词后不用原形或过去式;✗ to pay:介词后不用不定式。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',5,'am2_l32_gp8','choice','{"stem":"\"She left after ___ the dress.\"(介词后面动词用 -ing 形式)","options":["take","took","taking","to take"],"answer_index":2,"stem_cn":"她拿了连衣裙后就离开了。","explanation_cn":"介词 after 后面动词用 -ing 形式。✓ after taking the dress 拿了连衣裙之后。✗ take / took:介词后不用原形或过去式;✗ to take:介词后不用不定式。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',6,NULL,'choice','{"stem":"美语里\"商店\"常说:","options":["market house","sell place","shop","store"],"answer_index":3,"explanation_cn":"美语里\"商店\"常说 store(大商店 department store);英式说 shop。✓ a large store 一家大商店。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',6,NULL,'choice','{"stem":"美语里\"包裹\"常说:","options":["package","wrap bag","parcel","box mail"],"answer_index":0,"explanation_cn":"美语里\"包裹\"常说 package;英式说 parcel。✓ took the package 拿起包裹。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',6,NULL,'choice','{"stem":"temptation 的意思是:","options":["邀请","诱惑","警告","惩罚"],"answer_index":1,"explanation_cn":"temptation = 诱惑。✓ the temptation to steal 偷窃的诱惑。\n顺带记:逮捕 = arrest;偷窃 = steal;包 = wrap."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',6,NULL,'choice','{"stem":"arrest 的意思是:","options":["追赶","审判","逮捕","释放"],"answer_index":2,"explanation_cn":"arrest = 逮捕。✓ When she was arrested 她被捕后。\n顺带记:释放 = release;追赶 = chase;诚实的 = honest."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',6,NULL,'choice','{"stem":"article(a few small articles)的意思是:","options":["文章标题","冠词","关节","物品,东西"],"answer_index":3,"explanation_cn":"article 在本课(a few small articles)意为\"物品、东西\"。✓ a few small articles 几样小商品。\n顺带记:连衣裙 = dress;售货员 = assistant;曾经 = once."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',6,NULL,'choice','{"stem":"once(as they once were)的意思是:","options":["曾经,以前","从不","一次就","立刻"],"answer_index":0,"explanation_cn":"once(as they once were)意为\"曾经、以前\"。✓ not so honest as they once were 不像从前那样诚实。\n顺带记:仅仅 = simply;诱惑 = temptation;诚实的 = honest."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',7,NULL,'cloze','{"stem":"第 1 空","context":"People are not ___1___ honest as they once were. One Monday there were ___2___ people than usual, so it was easier ___3___ the detective to watch her. The woman took the package and walked out without ___4___.","blank_no":1,"options":["so","very","too","more"],"answer_index":0,"explanation_cn":"\"不如…那样\"用 not so … as。✓ People are not so honest as they once were。\n✗ very / too:不构成比较;✗ more:意思相反。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',7,NULL,'cloze','{"stem":"第 2 空","context":"People are not ___1___ honest as they once were. One Monday there were ___2___ people than usual, so it was easier ___3___ the detective to watch her. The woman took the package and walked out without ___4___.","blank_no":2,"options":["fewer","less","few","little"],"answer_index":0,"explanation_cn":"\"比…少\",修饰可数名词(people)用 fewer。✓ fewer people than usual。\n✗ less / little:修饰不可数;✗ few:缺少比较含义。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',7,NULL,'cloze','{"stem":"第 3 空","context":"People are not ___1___ honest as they once were. One Monday there were ___2___ people than usual, so it was easier ___3___ the detective to watch her. The woman took the package and walked out without ___4___.","blank_no":3,"options":["for","of","to","with"],"answer_index":0,"explanation_cn":"it 作形式主语,动作发出者前用 for。✓ it was easier for the detective to watch her。\n✗ of:此处不表人品;✗ to / with:不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',7,NULL,'cloze','{"stem":"第 4 空","context":"People are not ___1___ honest as they once were. One Monday there were ___2___ people than usual, so it was easier ___3___ the detective to watch her. The woman took the package and walked out without ___4___.","blank_no":4,"options":["paying","pay","paid","to pay"],"answer_index":0,"explanation_cn":"介词 without 后面动词用 -ing。✓ walked out without paying 没付钱就走了。\n✗ pay / paid:介词后不用原形或过去式;✗ to pay:介词后不用不定式。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',8,NULL,'choice','{"stem":"Who did the detective watch in the large store?","options":["The store manager","A well-dressed woman","A young shop assistant","A police officer"],"answer_index":1,"explanation_cn":"课文说 A detective recently watched a well-dressed woman,侦探盯上一位穿着讲究的妇女。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',8,NULL,'choice','{"stem":"What did the woman do with the expensive dress?","options":["She tried it on and left it","She paid for it at once","She took it and walked out without paying","She returned it to the assistant"],"answer_index":2,"explanation_cn":"课文说 the woman simply took the package and walked out of the store without paying,她拿了包裹没付钱就走。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',8,NULL,'choice','{"stem":"Who was the assistant who wrapped up the dress?","options":["The woman''s daughter","A stranger","The store manager","The detective''s wife"],"answer_index":0,"explanation_cn":"课文说 the detective found out that the assistant was her daughter,那售货员是妇女的女儿。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',9,NULL,'choice','{"stem":"你想说\"他和我年龄一样大\"(和…一样用 as…as):","options":["He is as old than I am.","He is so old as I am.","He is as old as I am.","He is more old as I am."],"answer_index":2,"explanation_cn":"\"和…一样\"用 as + 形容词 + as。✓ He is as old as I am. 场合:比较两人某方面相同。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',9,NULL,'choice','{"stem":"你想说\"她不像我们想的那么聪明\"(不如…那样):","options":["She is not so intelligent as we think.","She is not so intelligent than we think.","She is not more intelligent so we think.","She is not intelligent than we think."],"answer_index":0,"explanation_cn":"\"不如…那样\"用 not so … as。✓ She is not so intelligent as we think. 场合:说某人达不到某种程度。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',9,NULL,'choice','{"stem":"你想说\"那妇女没付钱就走了\"(介词后用 -ing):","options":["The woman walked out without pay.","The woman walked out without paying.","The woman walked out without paid.","The woman walked out without to pay."],"answer_index":1,"explanation_cn":"介词 without 后面用 -ing。✓ walked out without paying. 场合:说做一件事时没做另一件事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"temptation 的意思是:","options":["惩罚","邀请","休息","诱惑"],"answer_index":3,"explanation_cn":"temptation = 诱惑。✓ the temptation to steal 偷窃的诱惑。\n顺带记:逮捕 = arrest;偷窃 = steal;物品 = article."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"arrest 的意思是:","options":["释放","逃跑","逮捕","雇用"],"answer_index":2,"explanation_cn":"arrest = 逮捕。✓ When she was arrested 她被捕后。\n顺带记:释放 = release;雇用 = employ;逃跑 = run away."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"\"People are not ___ honest as they once were.\"(表示''不如…那样'')","options":["very","so","too","more"],"answer_index":1,"stem_cn":"人们不像从前那样诚实了。","explanation_cn":"\"不如…那样\"用 not so … as。✓ People are not so honest as they once were 人们不像从前那样诚实。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"\"He wrapped it up as quickly ___ possible.\"(表示''尽可能…'')","options":["so","than","that","as"],"answer_index":3,"stem_cn":"他尽快把它包好。","explanation_cn":"\"尽可能…\"用 as … as possible。✓ as quickly as possible 尽可能快。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"\"People are not so honest as they once were.\" 这句话的意思是:","options":["人们不像从前那样诚实了。","人们一向都很诚实。","人们比从前更诚实了。","人们从不诚实。"],"answer_index":0,"explanation_cn":"People are not so honest as they once were. not so…as 表\"不如…那样\",意思是\"人们不像从前那样诚实了\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"\"She took the package and walked out without paying.\" 这句话的意思是:","options":["她买了包裹很高兴。","她把包裹还了回去。","她拿了包裹没付钱就走了。","她付了钱才拿走包裹。"],"answer_index":2,"explanation_cn":"She took the package and walked out without paying. without paying 表\"没付钱\",意思是\"她拿了包裹没付钱就走了\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"Why was it easier for the detective to watch the woman that Monday?","options":["There were fewer people in the store than usual","The store was brightly lit","The woman was completely alone","The woman moved very slowly"],"answer_index":0,"passage":"People are not so honest as they once were. The temptation to steal is greater than ever before — especially in large stores. A detective recently watched a well-dressed woman who always went into a large store on Monday mornings. One Monday, there were fewer people in the store than usual when the woman came in, so it was easier for the detective to watch her. The woman first bought a few small articles. After a little time, she chose one of the most expensive dresses in the store and handed it to an assistant who wrapped it up for her as quickly as possible. Then the woman simply took the package and walked out of the store without paying. When she was arrested, the detective found out that the assistant was her daughter. The girl ''gave'' her mother a free dress once a week!","explanation_cn":"课文说 there were fewer people in the store than usual… so it was easier for the detective to watch her,人少了更好监视。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"What did the detective find out when the woman was arrested?","options":["The store was closing down","The dress was not expensive","The woman had paid after all","The assistant was her daughter"],"answer_index":3,"passage":"People are not so honest as they once were. The temptation to steal is greater than ever before — especially in large stores. A detective recently watched a well-dressed woman who always went into a large store on Monday mornings. One Monday, there were fewer people in the store than usual when the woman came in, so it was easier for the detective to watch her. The woman first bought a few small articles. After a little time, she chose one of the most expensive dresses in the store and handed it to an assistant who wrapped it up for her as quickly as possible. Then the woman simply took the package and walked out of the store without paying. When she was arrested, the detective found out that the assistant was her daughter. The girl ''gave'' her mother a free dress once a week!","explanation_cn":"课文结尾 the detective found out that the assistant was her daughter,售货员竟是妇女的女儿。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"Who was the thief?","options":["The well-dressed woman","The detective","An honest customer","The store manager"],"answer_index":0,"audio":"People are not so honest as they once were. The temptation to steal is greater than ever before — especially in large stores. A detective recently watched a well-dressed woman who always went into a large store on Monday mornings. One Monday, there were fewer people in the store than usual when the woman came in, so it was easier for the detective to watch her. The woman first bought a few small articles. After a little time, she chose one of the most expensive dresses in the store and handed it to an assistant who wrapped it up for her as quickly as possible. Then the woman simply took the package and walked out of the store without paying. When she was arrested, the detective found out that the assistant was her daughter. The girl ''gave'' her mother a free dress once a week!","explanation_cn":"课文说穿着讲究的妇女拿了裙子没付钱走了,她(靠女儿帮忙)才是小偷。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l32',10,NULL,'choice','{"stem":"How often did the girl ''give'' her mother a free dress?","options":["Never","Once a week","Once a year","Every day"],"answer_index":1,"audio":"People are not so honest as they once were. The temptation to steal is greater than ever before — especially in large stores. A detective recently watched a well-dressed woman who always went into a large store on Monday mornings. One Monday, there were fewer people in the store than usual when the woman came in, so it was easier for the detective to watch her. The woman first bought a few small articles. After a little time, she chose one of the most expensive dresses in the store and handed it to an assistant who wrapped it up for her as quickly as possible. Then the woman simply took the package and walked out of the store without paying. When she was arrested, the detective found out that the assistant was her daughter. The girl ''gave'' her mother a free dress once a week!","explanation_cn":"课文结尾 The girl ''gave'' her mother a free dress once a week,女儿每星期\"送\"母亲一件免费连衣裙。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
